  let scanDebounceTimer = null;
  let isScanningPanels = false;

  function scheduleScanPanels(immediate = false) {
    if (scanDebounceTimer) clearTimeout(scanDebounceTimer);
    if (immediate) {
      scanAndEnhancePanels();
    } else {
      scanDebounceTimer = setTimeout(() => {
        scanDebounceTimer = null;
        scanAndEnhancePanels();
      }, 500);
    }
  }

  let studioPillHeartbeat = null;
  let studioPillEl = null;
  const CORTEX_TOP_BAR_ID = 'vest-cortex-top-bar';
  const CORTEX_BAR_HEIGHT = 44;
  const CORTEX_BAR_MARGIN_BOTTOM = 8;
  let lastAdjustedContentEl = null;

  function getMainHeaderElement() {
    // 1. Direct semantic header or nav elements
    const semanticHeaders = Array.from(document.querySelectorAll('header, nav, [role="banner"], [role="navigation"]')).filter(el => {
      if (el.id === CORTEX_TOP_BAR_ID || el.id.startsWith('vest-') || el.closest('#' + CORTEX_TOP_BAR_ID)) return false;
      const r = el.getBoundingClientRect();
      return r.top >= -5 && r.top <= 5 && r.width >= window.innerWidth * 0.5 && r.height >= 26 && r.height <= 95;
    });
    if (semanticHeaders.length > 0) return semanticHeaders[0];

    // 2. High-level elements at top containing primary navigation keywords
    const topDivs = Array.from(document.querySelectorAll('body > div, body > div > div, body > div > header, body > header, #__next > header, #__next > div > header, #root > header')).filter(el => {
      if (el.id === CORTEX_TOP_BAR_ID || el.id.startsWith('vest-') || el.closest('#' + CORTEX_TOP_BAR_ID)) return false;
      const r = el.getBoundingClientRect();
      if (r.top > 5 || r.top < -5 || r.width < window.innerWidth * 0.5 || r.height < 26 || r.height > 95) return false;
      const txt = el.textContent || '';
      return (txt.includes('Trade') && (txt.includes('Markets') || txt.includes('Dashboard') || txt.includes('Competitions') || txt.includes('Portfolio'))) || txt.includes('My Funded') || txt.includes('Kalshi') || (txt.includes('MARKETS') && (txt.includes('PERPETUALS') || txt.includes('PORTFOLIO')));
    });
    if (topDivs.length > 0) return topDivs[0];

    return null;
  }

  function getMainHeaderBottom() {
    const activeFirm = typeof getActivePerpFirm === 'function' ? getActivePerpFirm() : null;
    if (activeFirm && activeFirm.topBarMode === 'custom' && activeFirm.customTopBarOffsetPx > 0) {
      return Math.round(activeFirm.customTopBarOffsetPx);
    }
    const header = getMainHeaderElement();
    if (header) {
      const r = header.getBoundingClientRect();
      if (r.bottom >= 26 && r.bottom <= 100) {
        return Math.round(r.bottom);
      }
    }
    const market = typeof findMarketSelectorElement === 'function' ? findMarketSelectorElement() : null;
    if (market && market.rowEl) {
      const mr = market.rowEl.getBoundingClientRect();
      if (mr.top >= 26 && mr.top <= 100) {
        return Math.round(mr.top);
      }
    }
    return 48;
  }

  function adjustLayoutForTopBar(headerBottom, barHeight, barMarginBottom = CORTEX_BAR_MARGIN_BOTTOM) {
    const root = document.documentElement;
    const body = document.body;
    if (!root || !body) return;

    if (root.classList.contains('vest-cortex-bottom-bar-active')) {
      root.classList.remove('vest-cortex-bottom-bar-active');
    }
    if (body.classList.contains('vest-cortex-bottom-bar-active')) {
      body.classList.remove('vest-cortex-bottom-bar-active');
    }
    root.classList.add('vest-cortex-top-bar-active');
    body.classList.add('vest-cortex-top-bar-active');

    const candidates = Array.from(body.children).filter(el => {
      if (el.id === CORTEX_TOP_BAR_ID || el.id.startsWith('vest-')) return false;
      const style = window.getComputedStyle(el);
      const rect = el.getBoundingClientRect();
      return style.position !== 'fixed' && style.position !== 'absolute' &&
        rect.top <= 5 && rect.width >= window.innerWidth * 0.7;
    });
    const appRoot = candidates.sort((a, b) =>
      (b.getBoundingClientRect().width * b.getBoundingClientRect().height) -
      (a.getBoundingClientRect().width * a.getBoundingClientRect().height)
    )[0];

    if (appRoot && appRoot.style.maxHeight && appRoot.style.maxHeight.includes('calc(100vh - 50px)')) {
      appRoot.style.removeProperty('max-height');
      appRoot.style.removeProperty('overflow-y');
    }

    const header = getMainHeaderElement();
    if (header) {
      const hStyle = window.getComputedStyle(header);
      if (hStyle.position === 'static') {
        header.style.setProperty('position', 'relative', 'important');
      }
      // Do NOT force an artificial high z-index (e.g. 1005) on the site header — let the exchange manage
      // its own header vs modal stacking order cleanly!
    }

    let contentEl = null;
    if (header && header.nextElementSibling && header.nextElementSibling.id !== CORTEX_TOP_BAR_ID) {
      contentEl = header.nextElementSibling;
    } else {
      const market = typeof findMarketSelectorElement === 'function' ? findMarketSelectorElement() : null;
      if (market && market.rowEl) {
        let curr = market.rowEl;
        while (
          curr &&
          curr.parentElement &&
          curr.parentElement !== document.body &&
          curr.parentElement.id !== '__next' &&
          curr.parentElement.id !== 'root'
        ) {
          if (header && curr.parentElement.contains(header) && curr.parentElement.children.length > 1) {
            break;
          }
          curr = curr.parentElement;
        }
        contentEl = curr;
      }
    }

    const totalTopOffset = (barHeight || CORTEX_BAR_HEIGHT) + (typeof barMarginBottom === 'number' ? barMarginBottom : CORTEX_BAR_MARGIN_BOTTOM);

    if (contentEl && contentEl !== header) {
      if (lastAdjustedContentEl && lastAdjustedContentEl !== contentEl) {
        lastAdjustedContentEl.style.removeProperty('margin-top');
        lastAdjustedContentEl.style.removeProperty('max-height');
      }
      lastAdjustedContentEl = contentEl;
      contentEl.style.setProperty('margin-top', `${totalTopOffset}px`, 'important');
      contentEl.style.setProperty('box-sizing', 'border-box', 'important');
      if (contentEl.offsetHeight > 200 || (header && contentEl === header.nextElementSibling)) {
        contentEl.style.setProperty('max-height', `calc(100vh - ${headerBottom + totalTopOffset}px)`, 'important');
      }
    }
  }

  function isHypernovaHost() {
    try {
      return Boolean(window.location && window.location.hostname && window.location.hostname.toLowerCase().includes('hypernova'));
    } catch (e) {
      return false;
    }
  }

  function getChartVisualsHostFirmId() {
    try {
      const host = String((window.location && window.location.hostname) || '').toLowerCase();
      if (host.includes('hypernova')) return 'hypernova';
      if (host.includes('myfundedperpetuals') || host.includes('myfundedperps')) return 'myfundedperpetuals';
      if (host.includes('kalshi')) return 'kalshipro';
    } catch (e) {}
    return null;
  }

  function isChartVisualsHost() {
    return Boolean(getChartVisualsHostFirmId());
  }

  function getChartVisualsHostDisplayName() {
    const id = getChartVisualsHostFirmId();
    if (id === 'hypernova') return 'Hypernova';
    if (id === 'myfundedperpetuals') return 'My Funded Perps';
    if (id === 'kalshipro') return 'Kalshi Pro';
    return 'Exchange';
  }

  // -------------------------------------------------------------
  // Multi-Venue Live Positions Scraper & TP/SL/BE/Close Executors
  // (Hypernova, My Funded Perpetuals, Kalshi Pro)
  // -------------------------------------------------------------
  let lastHypernovaPositionsSig = '';
  let hypernovaPositionsTimer = null;
  let lastKnownDomPositions = [];
  let lastApiCapturedPositions = [];
  let lastApiPositionsCapturedAt = 0;
  let hypernovaSyncTickCount = 0;

  function normalizeHypernovaBaseSymbol(raw) {
    const rawStr = String(raw || '').toUpperCase().trim();
    let s = rawStr
      .replace(/^.*:/, '')
      .replace(/\b(PERP|PERPETUAL|USD|USDT|USDC)\b/gi, '')
      .replace(/[^A-Z0-9]/g, '');
    s = s.replace(/(PERPETUAL|PERP|USDT|USDC|USD)$/i, '');
    s = s.replace(/(PERPETUAL|PERP|USDT|USDC|USD)$/i, '');
    // Kalshi Pro perpetual contract tickers carry a leading "KX" prefix (e.g. KXTSMPERP -> TSM, KXHYPEPERP -> HYPE, KXUSTECH100PERP -> USTECH100)
    if (/^KX[A-Z0-9]{2,}$/.test(s) && s.length >= 4) {
      s = s.slice(2);
    }
    return s;
  }

  function extractSymbolFromCellText(raw) {
    const cleaned = String(raw || '')
      .replace(/\b\d+(?:\.\d+)?x\b/gi, ' ')
      .replace(/\b(long|short|cross|isolated|perp|perpetual)\b/gi, ' ')
      .trim();
    const m = cleaned.match(/\b([A-Z][A-Z0-9]{1,13}(?:[-/_](?:USD|USDT|USDC|PERP))?|\d{2,4}[A-Z]{2,10}(?:[-/_](?:USD|USDT|USDC|PERP))?)\b/i);
    return m ? normalizeHypernovaBaseSymbol(m[1]) : '';
  }

  function parseHypernovaNumber(text) {
    const cleaned = String(text || '').replace(/[\u2212\u2013]/g, '-').replace(/,/g, '');
    const m = cleaned.match(/[+-]?\s*\$?\s*([+-]?\d+(?:\.\d+)?)/);
    if (!m) return NaN;
    const rawSign = cleaned.trim().startsWith('-') || m[0].includes('-') ? -1 : 1;
    const val = parseFloat(m[1]);
    return Number.isFinite(val) ? Math.abs(val) * rawSign : NaN;
  }

  function getHypernovaDecimalPlaces(text) {
    const cleaned = String(text || '').replace(/,/g, '');
    const m = cleaned.match(/\d+\.(\d+)/);
    return m ? m[1].length : 0;
  }

  function formatHypernovaOrderPrice(price, decimalsHint = null, firmIdOverride = null) {
    const p = Number(price);
    if (!Number.isFinite(p) || p <= 0) return '';
    const firmId = firmIdOverride || (typeof getChartVisualsHostFirmId === 'function' ? getChartVisualsHostFirmId() : 'hypernova') || 'hypernova';
    if (firmId === 'hypernova') {
      // Hypernova (Hyperliquid-style perp engine) uses 5 significant figures (capped at 6 decimals).
      const intDigits = p >= 1 ? Math.floor(Math.log10(p)) + 1 : 0;
      const maxSigFigDecimals = p >= 1 ? Math.max(0, 5 - intDigits) : 6;
      let decimals = maxSigFigDecimals;
      if (Number.isInteger(decimalsHint) && decimalsHint >= 0) {
        decimals = Math.min(decimalsHint, maxSigFigDecimals);
      }
      if (decimals === 0) return String(Math.round(p));
      return p.toFixed(decimals);
    }
    // My Funded Perpetuals & Kalshi Pro: respect exact displayed row precision when available, else clean magnitude precision
    if (Number.isInteger(decimalsHint) && decimalsHint >= 0) {
      const d = Math.min(6, decimalsHint);
      return d === 0 ? String(Math.round(p)) : p.toFixed(d);
    }
    if (p >= 1000) return p.toFixed(2);
    if (p >= 10) return p.toFixed(2);
    if (p >= 1) return p.toFixed(3);
    if (p >= 0.01) return p.toFixed(4);
    return p.toFixed(6);
  }

  function setReactNativeInputValue(input, nextValue) {
    if (!input) return false;
    try {
      input.focus();
      const valStr = String(nextValue ?? '');
      const proto = Object.getPrototypeOf(input);
      const setter = Object.getOwnPropertyDescriptor(proto, 'value')?.set ||
        Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value')?.set;
      // Reset React's internal _valueTracker so controlled React inputs always fire onChange
      const tracker = input._valueTracker;
      if (tracker && typeof tracker.setValue === 'function') {
        tracker.setValue(valStr === '' ? '__cortex_prev__' : '');
      }
      if (setter) setter.call(input, valStr);
      else input.value = valStr;
      try {
        input.dispatchEvent(new InputEvent('input', {
          bubbles: true,
          cancelable: true,
          data: valStr,
          inputType: valStr === '' ? 'deleteContentBackward' : 'insertText'
        }));
      } catch (e) {
        input.dispatchEvent(new Event('input', { bubbles: true }));
      }
      input.dispatchEvent(new Event('change', { bubbles: true }));
      return true;
    } catch (e) {
      return false;
    }
  }

  function dispatchHypernovaClick(el) {
    if (!el) return false;
    try {
      if (typeof el.focus === 'function') {
        try { el.focus({ preventScroll: true }); } catch (e) {}
      }
      const rect = typeof el.getBoundingClientRect === 'function' ? el.getBoundingClientRect() : { left: 0, top: 0, width: 0, height: 0 };
      const clientX = rect.left + rect.width / 2;
      const clientY = rect.top + rect.height / 2;
      try {
        el.dispatchEvent(new PointerEvent('pointerdown', { bubbles: true, cancelable: true, button: 0, buttons: 1, clientX, clientY, pointerType: 'mouse', isPrimary: true }));
      } catch (e) {}
      try {
        el.dispatchEvent(new MouseEvent('mousedown', { bubbles: true, cancelable: true, button: 0, buttons: 1, clientX, clientY }));
      } catch (e) {}
      try {
        el.dispatchEvent(new PointerEvent('pointerup', { bubbles: true, cancelable: true, button: 0, buttons: 0, clientX, clientY, pointerType: 'mouse', isPrimary: true }));
      } catch (e) {}
      try {
        el.dispatchEvent(new MouseEvent('mouseup', { bubbles: true, cancelable: true, button: 0, buttons: 0, clientX, clientY }));
      } catch (e) {}
      if (typeof el.click === 'function') {
        el.click();
      } else {
        el.dispatchEvent(new MouseEvent('click', { bubbles: true, cancelable: true, button: 0, clientX, clientY }));
      }
      return true;
    } catch (e) {
      return false;
    }
  }

  function waitForHypernovaCondition(fn, timeoutMs = 1500, intervalMs = 40) {
    return new Promise((resolve) => {
      const immediate = (() => { try { return fn(); } catch (e) { return null; } })();
      if (immediate) {
        resolve(immediate);
        return;
      }
      const started = Date.now();
      const timer = setInterval(() => {
        let res = null;
        try { res = fn(); } catch (e) {}
        if (res) {
          clearInterval(timer);
          resolve(res);
          return;
        }
        if (Date.now() - started >= timeoutMs) {
          clearInterval(timer);
          resolve(null);
        }
      }, intervalMs);
    });
  }

  async function ensureHypernovaPositionsTabActive() {
    if (document.querySelector('tr[data-testid^="positions-row-"], [data-testid^="positions-mobile-row-"]')) return true;
    const kalshiBlotter = document.querySelector('div[data-perps-blotter="true"]');
    if (kalshiBlotter) {
      const hasKalshiPos = Boolean(
        kalshiBlotter.querySelector('[role="list"][aria-label="Positions"] a.perps-blotter__market-name') ||
        kalshiBlotter.querySelector('[role="table"] [role="row"] a.perps-blotter__market-name')
      );
      if (hasKalshiPos) return true;
    }
    const tabs = Array.from(document.querySelectorAll('[role="tablist"] [role="tab"], .trade-tabs-list [role="tab"]'));
    const posTab = tabs.find(t => /^positions\b/i.test((t.innerText || t.textContent || '').trim()));
    if (posTab && posTab.getAttribute('aria-selected') !== 'true') {
      dispatchHypernovaClick(posTab);
      await waitForHypernovaCondition(() =>
        document.querySelector('tr[data-testid^="positions-row-"], [data-testid^="positions-mobile-row-"]') ||
        document.querySelector('div[data-perps-blotter="true"] a.perps-blotter__market-name') ||
        findHypernovaPositionsTableAndRows(),
        550,
        40
      );
    }
    return true;
  }

  function parseKalshiTpSlSpans(container) {
    let tpPrice = null;
    let slPrice = null;
    if (!container) return { tpPrice, slPrice };
    const tpEl = container.querySelector('[data-tpsl-focus="take_profit"]');
    const slEl = container.querySelector('[data-tpsl-focus="stop_loss"]');
    if (tpEl) {
      const v = Math.abs(parseHypernovaNumber(tpEl.innerText || tpEl.textContent || ''));
      if (Number.isFinite(v) && v > 0) tpPrice = v;
    }
    if (slEl) {
      const v = Math.abs(parseHypernovaNumber(slEl.innerText || slEl.textContent || ''));
      if (Number.isFinite(v) && v > 0) slPrice = v;
    }
    return { tpPrice, slPrice };
  }

  function extractKalshiRowSymbol(el) {
    const link = el && el.querySelector ? el.querySelector('a.perps-blotter__market-name') : null;
    if (link) {
      const txt = (link.innerText || link.textContent || '').trim();
      if (txt) {
        const sym = normalizeHypernovaBaseSymbol(txt);
        if (sym) return sym;
      }
      const href = String(link.getAttribute('href') || '');
      const hm = href.match(/\/perpetuals\/([^/?#]+)/i);
      if (hm) return normalizeHypernovaBaseSymbol(hm[1]);
    }
    return '';
  }

  function scrapeKalshiProOpenPositions() {
    const blotter = document.querySelector('div[data-perps-blotter="true"]');
    if (!blotter) return { foundTable: false, positions: [] };

    // Verify Positions tab is active (so Orders / Trade history rows are never misread as open positions)
    const tabs = Array.from(blotter.querySelectorAll('[role="tablist"] [role="tab"]'));
    const posTab = tabs.find(t => /^positions\b/i.test((t.innerText || t.textContent || '').trim()));
    if (posTab && posTab.getAttribute('aria-selected') === 'false') {
      return { foundTable: false, positions: [] };
    }

    const positions = [];

    // Presentation A: Cards mode (narrower viewports, e.g. 1145px) -> `[role="list"][aria-label="Positions"] li`
    const cardList = blotter.querySelector('[role="list"][aria-label="Positions"]');
    if (cardList) {
      const cards = Array.from(cardList.querySelectorAll('li')).filter(li => li.querySelector('a.perps-blotter__market-name'));
      for (const li of cards) {
        const symbol = extractKalshiRowSymbol(li);
        if (!symbol) continue;
        const sideEl = li.querySelector('[data-side]');
        const sideAttr = sideEl ? String(sideEl.getAttribute('data-side') || '').toLowerCase() : '';
        const liAria = String(li.getAttribute('aria-label') || '').toLowerCase();
        const side = (sideAttr === 'short' || /\bshort\b/.test(liAria)) ? 'short' : 'long';

        const fields = {};
        li.querySelectorAll('[data-card-field="true"]').forEach(f => {
          const dt = f.querySelector('dt');
          const dd = f.querySelector('dd');
          if (dt && dd) {
            const k = (dt.innerText || dt.textContent || '').replace(/\s+/g, ' ').trim().toLowerCase();
            fields[k] = (dd.innerText || dd.textContent || '').replace(/\s+/g, ' ').trim();
          }
        });

        const entryText = fields['avg entry'] || fields['entry'] || fields['entry price'] || '';
        const markText = fields['mark price'] || fields['current price'] || fields['mark'] || '';
        const qtyText = fields['quantity'] || fields['size'] || '';
        const valText = fields['value'] || '';

        const entryPrice = Math.abs(parseHypernovaNumber(entryText));
        if (!Number.isFinite(entryPrice) || entryPrice <= 0) continue;
        const markPrice = Math.abs(parseHypernovaNumber(markText));
        const sizeQty = Math.abs(parseHypernovaNumber(qtyText));
        const notionalUsd = Math.abs(parseHypernovaNumber(valText));

        let unrealizedPnl = NaN;
        const headerEl = li.querySelector('[data-card-header="true"]');
        if (headerEl) {
          const pnlSpan = headerEl.querySelector('[data-tone="positive"], [data-tone="negative"]');
          const pnlRaw = pnlSpan ? (pnlSpan.innerText || pnlSpan.textContent || '') : (headerEl.innerText || '');
          const mPnl = pnlRaw.replace(/,/g, '').match(/([+-]?\s*\$\s*\d+(?:\.\d+)?)/);
          if (mPnl) {
            unrealizedPnl = parseHypernovaNumber(mPnl[1]);
            if (pnlSpan && pnlSpan.getAttribute('data-tone') === 'negative' && unrealizedPnl > 0) {
              unrealizedPnl = -Math.abs(unrealizedPnl);
            }
          }
        }

        const { tpPrice, slPrice } = parseKalshiTpSlSpans(li);
        const priceDecimals = Math.max(getHypernovaDecimalPlaces(entryText), getHypernovaDecimalPlaces(markText));
        positions.push({
          symbol,
          side,
          entryPrice,
          markPrice: Number.isFinite(markPrice) && markPrice > 0 ? markPrice : null,
          sizeQty: Number.isFinite(sizeQty) && sizeQty > 0 ? sizeQty : (Number.isFinite(notionalUsd) ? notionalUsd / entryPrice : null),
          notionalUsd: Number.isFinite(notionalUsd) && notionalUsd > 0 ? notionalUsd : (Number.isFinite(sizeQty) ? sizeQty * entryPrice : null),
          unrealizedPnl: Number.isFinite(unrealizedPnl) ? unrealizedPnl : null,
          tpPrice,
          slPrice,
          priceDecimals
        });
      }
      return { foundTable: true, positions };
    }

    // Presentation B: Desktop CSS-grid Table mode -> `[role="table"] [role="row"]`
    const tableEl = blotter.querySelector('[role="table"]');
    if (tableEl) {
      const allRows = Array.from(tableEl.querySelectorAll('[role="row"]'));
      const headerRow = allRows[0];
      const headerCells = headerRow
        ? Array.from(headerRow.children).map(c => (c.innerText || c.textContent || '').replace(/\s+/g, ' ').trim().toLowerCase())
        : [];
      const idxPos = headerCells.findIndex(h => /position|size|qty/.test(h));
      const idxMark = headerCells.findIndex(h => /current\s*price|mark/.test(h));
      const idxEntry = headerCells.findIndex(h => /entry/.test(h));
      const idxPnl = headerCells.findIndex(h => /\bpnl\b|profit/.test(h));

      for (const row of allRows.slice(1)) {
        if (!row.querySelector('a.perps-blotter__market-name')) continue;
        const symbol = extractKalshiRowSymbol(row);
        if (!symbol) continue;
        const sideEl = row.querySelector('[data-side]');
        const sideAttr = sideEl ? String(sideEl.getAttribute('data-side') || '').toLowerCase() : '';
        const side = sideAttr === 'short' ? 'short' : 'long';

        const cols = Array.from(row.children);
        const posCol = idxPos >= 0 ? cols[idxPos] : cols[1];
        const markCol = idxMark >= 0 ? cols[idxMark] : cols[2];
        const entryCol = idxEntry >= 0 ? cols[idxEntry] : cols[3];
        const pnlCol = idxPnl >= 0 ? cols[idxPnl] : cols[6];

        // Entry / Liq cell is stacked (`$62.420` on first line, `Liq $80.421` on second line)
        const entryLines = entryCol
          ? (entryCol.innerText || entryCol.textContent || '').split(/\r?\n/).map(s => s.trim()).filter(Boolean)
          : [];
        const entryText = entryLines.find(l => !/^liq/i.test(l)) || entryLines[0] || '';
        const markText = markCol ? (markCol.innerText || markCol.textContent || '').trim() : '';

        const entryPrice = Math.abs(parseHypernovaNumber(entryText));
        if (!Number.isFinite(entryPrice) || entryPrice <= 0) continue;
        const markPrice = Math.abs(parseHypernovaNumber(markText));

        // Position cell is stacked (`0.7 HYPE` on line 1, `$43.6947` on line 2)
        const posLines = posCol
          ? (posCol.innerText || posCol.textContent || '').split(/\r?\n/).map(s => s.trim()).filter(Boolean)
          : [];
        let sizeQty = NaN;
        let notionalUsd = NaN;
        for (const pl of posLines) {
          if (pl.includes('$') && !Number.isFinite(notionalUsd)) {
            notionalUsd = Math.abs(parseHypernovaNumber(pl));
          } else if (!pl.includes('$') && !Number.isFinite(sizeQty)) {
            sizeQty = Math.abs(parseHypernovaNumber(pl));
          }
        }
        if (!Number.isFinite(sizeQty) && Number.isFinite(notionalUsd) && entryPrice > 0) sizeQty = notionalUsd / entryPrice;
        if (!Number.isFinite(notionalUsd) && Number.isFinite(sizeQty) && entryPrice > 0) notionalUsd = sizeQty * entryPrice;

        let unrealizedPnl = NaN;
        if (pnlCol) {
          const pnlText = (pnlCol.innerText || pnlCol.textContent || '').trim();
          unrealizedPnl = parseHypernovaNumber(pnlText);
          const negTone = pnlCol.querySelector('[data-tone="negative"]');
          if (negTone && unrealizedPnl > 0) unrealizedPnl = -Math.abs(unrealizedPnl);
        }

        const { tpPrice, slPrice } = parseKalshiTpSlSpans(row);
        const priceDecimals = Math.max(getHypernovaDecimalPlaces(entryText), getHypernovaDecimalPlaces(markText));
        positions.push({
          symbol,
          side,
          entryPrice,
          markPrice: Number.isFinite(markPrice) && markPrice > 0 ? markPrice : null,
          sizeQty: Number.isFinite(sizeQty) && sizeQty > 0 ? sizeQty : null,
          notionalUsd: Number.isFinite(notionalUsd) && notionalUsd > 0 ? notionalUsd : null,
          unrealizedPnl: Number.isFinite(unrealizedPnl) ? unrealizedPnl : null,
          tpPrice,
          slPrice,
          priceDecimals
        });
      }
      return { foundTable: true, positions };
    }

    // If the Positions tab IS selected on Kalshi Pro and neither cardList nor tableEl is mounted,
    // Kalshi Pro is showing its empty state (0 open positions) — treat as authoritative empty!
    if (posTab && (posTab.getAttribute('aria-selected') === 'true' || posTab.getAttribute('data-state') === 'active')) {
      return { foundTable: true, positions: [] };
    }
    return { foundTable: false, positions: [] };
  }

  function findKalshiProPositionRowBySymbol(symbol) {
    const targetSym = normalizeHypernovaBaseSymbol(symbol);
    const blotter = document.querySelector('div[data-perps-blotter="true"]');
    if (!blotter) return null;
    const candidates = [
      ...Array.from(blotter.querySelectorAll('[role="list"][aria-label="Positions"] li')),
      ...Array.from(blotter.querySelectorAll('[role="table"] [role="row"]'))
    ].filter(el => Boolean(el.querySelector('a.perps-blotter__market-name')));

    for (const row of candidates) {
      const rowSym = extractKalshiRowSymbol(row);
      if (!targetSym || rowSym === targetSym) {
        const tpSlTrigger =
          row.querySelector('button[aria-label="Edit TP/SL"]') ||
          Array.from(row.querySelectorAll('button')).find(b => /edit\s*tp\s*\/?\s*sl/i.test((b.innerText || b.textContent || '').trim())) ||
          null;
        const closeTrigger =
          row.querySelector('button[data-action="close"]') ||
          row.querySelector('button[aria-label="Close"]') ||
          Array.from(row.querySelectorAll('button')).find(b => /^close$/i.test((b.innerText || b.textContent || '').trim())) ||
          null;
        const { tpPrice, slPrice } = parseKalshiTpSlSpans(row);
        const rowText = (row.innerText || row.textContent || '');
        const priceMatch = rowText.match(/\$[\d,]+\.(\d+)/);
        const priceDecimals = priceMatch ? priceMatch[1].length : null;
        return {
          row,
          cells: [],
          headers: [],
          idxTpSl: -1,
          tpSlTrigger,
          closeTrigger,
          priceDecimals,
          existingTpPrice: tpPrice,
          existingSlPrice: slPrice,
          isKalshiPro: true
        };
      }
    }
    return null;
  }

  function findHypernovaPositionsTableAndRows() {
    // Fast-path: Hypernova's exact native positions rows (`tr[data-testid^="positions-row-"]`)
    const nativeRows = Array.from(document.querySelectorAll('tr[data-testid^="positions-row-"]')).filter(r => {
      const rr = r.getBoundingClientRect();
      return rr.width > 0 && rr.height > 0;
    });
    if (nativeRows.length > 0) {
      const table = nativeRows[0].closest('table, [role="table"]') || nativeRows[0].parentElement;
      const headerEls = table
        ? Array.from(table.querySelectorAll('thead th, thead [role="columnheader"]'))
        : [];
      const headers = headerEls.map(h => (h.innerText || h.textContent || '').replace(/\s+/g, ' ').trim().toLowerCase());
      return { table, headers, rows: nativeRows, isNativeHypernova: true };
    }

    const tables = Array.from(document.querySelectorAll('table, [role="table"]'));
    for (const table of tables) {
      const rect = table.getBoundingClientRect();
      if (rect.width <= 0 || rect.height <= 0) continue;
      const headerEls = Array.from(table.querySelectorAll('thead th, thead [role="columnheader"], [role="row"]:first-child [role="columnheader"]'));
      const headers = headerEls.map(h => (h.innerText || h.textContent || '').replace(/\s+/g, ' ').trim().toLowerCase());
      const headerLine = headers.join(' | ');
      if (!headerLine) continue;
      const looksLikeOpenPositions =
        (headerLine.includes('entry') || headerLine.includes('open price') || headerLine.includes('avg')) &&
        (headerLine.includes('size') || headerLine.includes('qty') || headerLine.includes('value') || headerLine.includes('position')) &&
        !headerLine.includes('exit price') &&
        !headerLine.includes('closed') &&
        !headerLine.includes('trigger price');
      if (!looksLikeOpenPositions) continue;
      const bodyRows = Array.from(table.querySelectorAll('tbody tr, [role="rowgroup"]:last-child [role="row"]')).filter(r => {
        const rr = r.getBoundingClientRect();
        return rr.width > 0 && rr.height > 0 && !r.querySelector('th');
      });
      return { table, headers, rows: bodyRows, isNativeHypernova: false };
    }
    return null;
  }

  function isPositionsTabElementSelected(tab) {
    if (!tab) return false;
    if (tab.getAttribute('aria-selected') === 'true') return true;
    if (tab.getAttribute('data-state') === 'active') return true;
    if (tab.getAttribute('data-selected') === 'true') return true;
    const cls = String(tab.className || '').toLowerCase();
    return /\bactive\b|\bselected\b/.test(cls);
  }

  function isPositionsEmptyStateVisibleInDom() {
    try {
      const panels = Array.from(document.querySelectorAll('[role="tabpanel"], .trade-tabs-panel, [class*="positions" i]'));
      for (let i = 0; i < panels.length && i < 40; i++) {
        const p = panels[i];
        if (!p || (p.id && p.id.startsWith('vest-'))) continue;
        if (p.hidden || p.getAttribute('data-state') === 'inactive') continue;
        const r = p.getBoundingClientRect();
        if (r.width <= 0 || r.height <= 0) continue;
        const txt = (p.innerText || p.textContent || '').replace(/\s+/g, ' ').trim();
        if (txt.length <= 320 && /\bno\s+(open|active)?\s*positions\b|opened\s+positions\s+will\s+appear\s+here/i.test(txt)) {
          return true;
        }
      }
      // Also check standalone empty-state containers (e.g. Hypernova unmounts <table> and shows "No Open Positions")
      const emptyEls = Array.from(document.querySelectorAll('div, p, span'));
      for (let i = 0; i < emptyEls.length; i++) {
        const el = emptyEls[i];
        if (!el || el.children.length > 2) continue;
        const t = (el.textContent || '').trim();
        if (t.length >= 12 && t.length <= 48 && /^no\s+(open|active)?\s*positions$/i.test(t)) {
          const r = el.getBoundingClientRect();
          if (r.width > 0 && r.height > 0 && r.top > window.innerHeight * 0.35) {
            return true;
          }
        }
      }
    } catch (e) {}
    return false;
  }

  function isCurrentChartOrderTicketFlat() {
    try {
      // Hypernova's right-hand order ticket explicitly renders "Current Position" -> "FLAT"
      const bodyText = document.body ? (document.body.innerText || '') : '';
      if (/Current\s+Position\s+FLAT\b/i.test(bodyText)) {
        return true;
      }
    } catch (e) {}
    return false;
  }

  function getCurrentTopChartSymbolForFlatCheck() {
    try {
      const triggerLabel = document.querySelector('[data-testid="symbol-toolbar-trigger-label"]');
      if (triggerLabel) {
        const sym = extractSymbolFromCellText(triggerLabel.innerText || triggerLabel.textContent || '');
        if (sym) return sym;
      }
      const mfpChart = document.querySelector('[data-chart-market]');
      if (mfpChart) {
        const sym = normalizeHypernovaBaseSymbol(mfpChart.getAttribute('data-chart-market') || '');
        if (sym) return sym;
      }
      const titleParts = String(document.title || '').split(/[|·\-]/);
      for (const part of titleParts) {
        const p = part.trim();
        if (!p || /^[\d$,.\s]+$/.test(p) || /hypernova|kalshi|funded/i.test(p)) continue;
        const sym = extractSymbolFromCellText(p);
        if (sym) return sym;
      }
    } catch (e) {}
    return '';
  }

  function scrapeHypernovaMobilePositions() {
    try {
      const mobileList = document.querySelector('[data-testid="positions-mobile-list"], .trade-positions-mobile-list');
      const rawRows = Array.from(document.querySelectorAll('[data-testid^="positions-mobile-row-"]'));
      const visibleRows = rawRows.filter(r => {
        const rr = typeof r.getBoundingClientRect === 'function' ? r.getBoundingClientRect() : { width: 1, height: 1 };
        return rr.width > 0 && rr.height > 0;
      });
      const listVisible = Boolean(
        mobileList &&
        ((() => {
          const lr = typeof mobileList.getBoundingClientRect === 'function' ? mobileList.getBoundingClientRect() : { width: 1, height: 1 };
          return lr.width > 0 && lr.height > 0;
        })())
      );
      if (!listVisible && visibleRows.length === 0) {
        return { foundTable: false, positions: [] };
      }

      const positions = [];
      const readMobileDetailText = (row, suffix) => {
        const el = row.querySelector(`[data-testid$="${suffix}"]`);
        if (!el) return '';
        const valEl = el.querySelector('.trade-positions-mobile-detail-value');
        if (valEl) return (valEl.innerText || valEl.textContent || '').replace(/\s+/g, ' ').trim();
        const labelEl = el.querySelector('.trade-positions-mobile-detail-label');
        const full = (el.innerText || el.textContent || '').replace(/\s+/g, ' ').trim();
        if (labelEl) {
          const lbl = (labelEl.innerText || labelEl.textContent || '').replace(/\s+/g, ' ').trim();
          if (lbl && full.startsWith(lbl)) return full.slice(lbl.length).trim();
        }
        return full;
      };

      for (const row of visibleRows) {
        const symTextEl = row.querySelector('[data-testid="symbol-text"]') || row.querySelector('[data-testid$="-coin"]');
        const rawSymStr = symTextEl
          ? (symTextEl.innerText || symTextEl.textContent || '').replace(/^market\b/i, '').trim()
          : '';
        const symbol = extractSymbolFromCellText(rawSymStr);
        if (!symbol) continue;

        const dataSide = String(row.getAttribute('data-side') || '').toLowerCase();
        const rowCls = String(row.className || '').toLowerCase();
        let side = null;
        if (dataSide === 'short' || rowCls.includes('row-short')) side = 'short';
        else if (dataSide === 'long' || rowCls.includes('row-long')) side = 'long';

        const sizeCell = row.querySelector('[data-testid$="-size"]');
        const sizeText = sizeCell
          ? (sizeCell.innerText || sizeCell.textContent || '').replace(/^\s*size\b/i, '').trim()
          : '';
        const rawSizeNum = parseHypernovaNumber(sizeText);
        if (!side && Number.isFinite(rawSizeNum) && rawSizeNum !== 0) {
          side = rawSizeNum < 0 ? 'short' : 'long';
        }
        if (!side) side = 'long';

        const pnlCell = row.querySelector('[data-testid$="-pnl"]');
        const pnlText = pnlCell
          ? (pnlCell.innerText || pnlCell.textContent || '').replace(/^\s*pnl\s*(\([^)]*\))?/i, '').trim()
          : '';
        let unrealizedPnl = parseHypernovaNumber(pnlText);
        if (Number.isFinite(unrealizedPnl) && pnlCell) {
          const negTone = pnlCell.querySelector('[data-tone="negative"], .trade-positions-pnl-negative, [class*="red"], [class*="rose"], [class*="destructive"]');
          const posTone = pnlCell.querySelector('[data-tone="positive"], .trade-positions-pnl-positive, [class*="green"], [class*="emerald"], [class*="success"]');
          if (negTone && !posTone && unrealizedPnl > 0) unrealizedPnl = -Math.abs(unrealizedPnl);
          else if (posTone && !negTone && unrealizedPnl < 0) unrealizedPnl = Math.abs(unrealizedPnl);
        }

        const entryText = readMobileDetailText(row, '-entry');
        const markText = readMobileDetailText(row, '-mark');
        const notionalText = readMobileDetailText(row, '-notional');
        const breachText = readMobileDetailText(row, '-breach');
        const tpSlEl = row.querySelector('[data-testid="position-tpsl"]') || row.querySelector('[data-testid$="-tpsl"]');
        const tpSlText = tpSlEl ? (tpSlEl.innerText || tpSlEl.textContent || '').replace(/^\s*tp\s*\/?\s*sl\b/i, '').trim() : '';

        const entryVal = entryText ? Math.abs(parseHypernovaNumber(entryText)) : NaN;
        const entryPrice = Number.isFinite(entryVal) && entryVal > 0 ? entryVal : null;
        const markVal = markText ? Math.abs(parseHypernovaNumber(markText)) : NaN;
        const markPrice = Number.isFinite(markVal) && markVal > 0 ? markVal : null;
        const rawValNum = notionalText ? Math.abs(parseHypernovaNumber(notionalText)) : NaN;

        let sizeQty = Number.isFinite(rawSizeNum) && rawSizeNum !== 0 ? Math.abs(rawSizeNum) : NaN;
        let notionalUsd = Number.isFinite(rawValNum) && rawValNum > 0 ? rawValNum : NaN;
        if (!Number.isFinite(sizeQty) && Number.isFinite(notionalUsd) && entryPrice) {
          sizeQty = notionalUsd / entryPrice;
        }
        if (!Number.isFinite(notionalUsd) && Number.isFinite(sizeQty) && entryPrice) {
          notionalUsd = sizeQty * entryPrice;
        }

        let tpPrice = null;
        let slPrice = null;
        if (tpSlText && !/view\s+orders/i.test(tpSlText)) {
          const slashParts = tpSlText.split('/');
          if (slashParts.length >= 2) {
            const tpVal = Math.abs(parseHypernovaNumber(slashParts[0]));
            const slVal = Math.abs(parseHypernovaNumber(slashParts[1]));
            if (Number.isFinite(tpVal) && tpVal > 0) tpPrice = tpVal;
            if (Number.isFinite(slVal) && slVal > 0) slPrice = slVal;
          }
        }

        const breachPriceRaw = breachText && !/at\s*floor|n\/a|^[-—]+$/i.test(breachText)
          ? Math.abs(parseHypernovaNumber(breachText))
          : NaN;
        const breachPrice = Number.isFinite(breachPriceRaw) && breachPriceRaw > 0 ? breachPriceRaw : null;
        const priceDecimals = (entryText || markText || breachText)
          ? Math.max(
              entryText ? getHypernovaDecimalPlaces(entryText) : 0,
              markText ? getHypernovaDecimalPlaces(markText) : 0,
              breachPrice ? getHypernovaDecimalPlaces(breachText) : 0
            )
          : null;

        if (!Number.isFinite(unrealizedPnl) && !Number.isFinite(sizeQty) && entryPrice === null) continue;

        positions.push({
          symbol,
          side,
          entryPrice,
          markPrice,
          breachPrice,
          sizeQty: Number.isFinite(sizeQty) && sizeQty > 0 ? sizeQty : null,
          notionalUsd: Number.isFinite(notionalUsd) && notionalUsd > 0 ? notionalUsd : null,
          unrealizedPnl: Number.isFinite(unrealizedPnl) ? unrealizedPnl : null,
          tpPrice,
          slPrice,
          priceDecimals,
          isMobileCard: true
        });
      }
      return { foundTable: true, positions, isMobileList: true };
    } catch (e) {}
    return { foundTable: false, positions: [] };
  }

  function scrapeVenueOpenPositionsWithMeta() {
    if (!isTopWindow || !isChartVisualsHost()) return { foundTable: false, positions: [] };
    if (getChartVisualsHostFirmId() === 'kalshipro') {
      return scrapeKalshiProOpenPositions();
    }
    const positions = [];
    try {
      const found = findHypernovaPositionsTableAndRows();
      if (!found) {
        // Hypernova mobile/compact layout (`<= 1299px`) renders div[data-testid="positions-mobile-list"] cards instead of <table>!
        const mobileRes = scrapeHypernovaMobilePositions();
        if (mobileRes.foundTable) {
          return mobileRes;
        }
        // Hypernova unmounts <table> completely when there are 0 open positions and shows "No Open Positions"!
        // If the Positions tab is selected OR an empty-positions state is visible, report authoritative 0 positions!
        const posTab = Array.from(document.querySelectorAll('[role="tablist"] [role="tab"], .trade-tabs-list [role="tab"]'))
          .find(t => /^positions\b/i.test((t.innerText || t.textContent || '').trim()));
        if ((posTab && isPositionsTabElementSelected(posTab)) || isPositionsEmptyStateVisibleInDom()) {
          return { foundTable: true, positions: [] };
        }
        return { foundTable: false, positions: [] };
      }
      const { headers, rows } = found;
      const idxSym = Math.max(0, headers.findIndex(h => /market|symbol|coin|pair|asset|contract|instrument|ticker/.test(h)));
      const idxSide = headers.findIndex(h => /\bside\b|\bdirection\b/.test(h));
      const idxSize = headers.findIndex(h => /\bsize\b|\bqty\b|\bquantity\b|\bamount\b|\bcontracts?\b/.test(h));
      const idxValue = headers.findIndex(h => /\bvalue\b|\bnotional\b|\bposition\b/.test(h));
      const idxEntry = headers.findIndex(h => /entry|open price|avg/.test(h));
      const idxMark = headers.findIndex(h => /mark|mid|oracle|index|last|current/.test(h));
      const idxBreach = headers.findIndex(h => /breach|liq\.?\s*price|liquidation/.test(h));
      const idxPnl = headers.findIndex(h => (/pnl|u\.?pnl|profit|total\s*trade/.test(h)) && !/realized|\brpnl\b/.test(h));
      const idxTpSl = headers.findIndex(h => /tp\s*\/?\s*sl|take\s*profit|stop\s*loss/.test(h));

      for (const row of rows) {
        if (row.querySelector('[data-slot="empty"]')) continue;
        const cells = Array.from(row.querySelectorAll('td, [role="cell"]'));
        if (cells.length < 3) continue;
        const cellTexts = cells.map(c => (c.innerText || c.textContent || '').replace(/\s+/g, ' ').trim());
        const rowText = cellTexts.join(' ');
        if (/no\s+(open\s+)?positions|sign\s+in\s+to\s+see/i.test(rowText)) continue;

        // Exact Hypernova data-testid cells when present
        const symTextEl = row.querySelector('[data-testid="symbol-text"]');
        const entryTd = row.querySelector('td[data-testid$="-entry"]');
        const markTd = row.querySelector('td[data-testid$="-mark"]');
        const breachTd = row.querySelector('td[data-testid$="-breach"]');
        const sizeTd = row.querySelector('td[data-testid$="-size"]');
        const valueTd = row.querySelector('td[data-testid$="-value"]');
        const pnlTd = row.querySelector('td[data-testid$="-pnl"]');
        const tpSlEl = row.querySelector('[data-testid="position-tpsl"]') || row.querySelector('td[data-testid$="-tpsl"]');

        const rawSymStr = symTextEl
          ? (symTextEl.innerText || symTextEl.textContent || '').trim()
          : (cellTexts[idxSym] || cellTexts[0] || '');
        const symbol = extractSymbolFromCellText(rawSymStr);
        if (!symbol) continue;

        const sideText = idxSide >= 0 ? (cellTexts[idxSide] || '') : '';
        const entryText = entryTd ? (entryTd.innerText || entryTd.textContent || '').trim() : (idxEntry >= 0 ? cellTexts[idxEntry] : '');
        const markText = markTd ? (markTd.innerText || markTd.textContent || '').trim() : (idxMark >= 0 ? cellTexts[idxMark] : '');
        const breachText = breachTd ? (breachTd.innerText || breachTd.textContent || '').trim() : (idxBreach >= 0 ? cellTexts[idxBreach] : '');
        const sizeText = sizeTd ? (sizeTd.innerText || sizeTd.textContent || '').trim() : (idxSize >= 0 ? cellTexts[idxSize] : '');
        const valueText = valueTd ? (valueTd.innerText || valueTd.textContent || '').trim() : (idxValue >= 0 ? cellTexts[idxValue] : '');
        const pnlText = pnlTd ? (pnlTd.innerText || pnlTd.textContent || '').trim() : (idxPnl >= 0 ? cellTexts[idxPnl] : '');
        const tpSlText = tpSlEl ? (tpSlEl.innerText || tpSlEl.textContent || '').trim() : (idxTpSl >= 0 ? cellTexts[idxTpSl] : '');

        // Detect side across Hypernova (`row-short`), MFP (`Side` column), and Kalshi (`Yes`/`No`/`Long`/`Short`)
        const rowCls = String(row.className || '').toLowerCase();
        let side = null;
        if (rowCls.includes('row-short') || /\b(short|sell|no)\b/i.test(sideText) || /\bshort\b/i.test(rawSymStr) || /\bshort\b/i.test(rowText)) side = 'short';
        else if (rowCls.includes('row-long') || /\b(long|buy|yes)\b/i.test(sideText) || /\blong\b/i.test(rawSymStr) || /\blong\b/i.test(rowText)) side = 'long';

        const entryPrice = Math.abs(parseHypernovaNumber(entryText));
        if (!Number.isFinite(entryPrice) || entryPrice <= 0) continue;

        const markPrice = Math.abs(parseHypernovaNumber(markText));
        const rawSizeNum = parseHypernovaNumber(sizeText);
        const rawValNum = Math.abs(parseHypernovaNumber(valueText));

        if (!side && Number.isFinite(rawSizeNum) && rawSizeNum !== 0) {
          side = rawSizeNum < 0 ? 'short' : 'long';
        }
        if (!side) {
          const checkCell = (idxSide >= 0 && cells[idxSide]) || cells[idxSym];
          const coloredEl = checkCell?.querySelector('[class*="red"], [class*="rose"], [class*="short"], [class*="sell"], [class*="danger"], [class*="destructive"]');
          const greenEl = checkCell?.querySelector('[class*="green"], [class*="emerald"], [class*="long"], [class*="buy"], [class*="success"]');
          if (coloredEl && !greenEl) side = 'short';
          else side = 'long';
        }

        let sizeQty = Number.isFinite(rawSizeNum) && rawSizeNum !== 0 ? Math.abs(rawSizeNum) : NaN;
        let notionalUsd = Number.isFinite(rawValNum) && rawValNum > 0 ? rawValNum : NaN;
        if (/\$/.test(sizeText) && !Number.isFinite(notionalUsd)) {
          notionalUsd = Math.abs(rawSizeNum);
          sizeQty = notionalUsd / entryPrice;
        }
        if (!Number.isFinite(sizeQty) && Number.isFinite(notionalUsd) && entryPrice > 0) {
          sizeQty = notionalUsd / entryPrice;
        }
        if (!Number.isFinite(notionalUsd) && Number.isFinite(sizeQty) && entryPrice > 0) {
          notionalUsd = sizeQty * entryPrice;
        }

        let unrealizedPnl = parseHypernovaNumber(pnlText);
        const pnlCellEl = pnlTd || (idxPnl >= 0 ? cells[idxPnl] : null);
        if (Number.isFinite(unrealizedPnl) && pnlCellEl) {
          const negTone = pnlCellEl.querySelector('[data-tone="negative"], .trade-positions-pnl-negative, [class*="red"], [class*="rose"], [class*="destructive"]');
          const posTone = pnlCellEl.querySelector('[data-tone="positive"], .trade-positions-pnl-positive, [class*="green"], [class*="emerald"], [class*="success"]');
          if (negTone && !posTone && unrealizedPnl > 0) unrealizedPnl = -Math.abs(unrealizedPnl);
          else if (posTone && !negTone && unrealizedPnl < 0) unrealizedPnl = Math.abs(unrealizedPnl);
        }

        let tpPrice = null;
        let slPrice = null;
        if (tpSlText) {
          const slashParts = tpSlText.split('/');
          if (slashParts.length >= 2) {
            const tpVal = Math.abs(parseHypernovaNumber(slashParts[0]));
            const slVal = Math.abs(parseHypernovaNumber(slashParts[1]));
            if (Number.isFinite(tpVal) && tpVal > 0) tpPrice = tpVal;
            if (Number.isFinite(slVal) && slVal > 0) slPrice = slVal;
          }
        }

        const breachPriceRaw = breachText && !/n\/a|^[-—]+$/i.test(breachText) ? Math.abs(parseHypernovaNumber(breachText)) : NaN;
        const breachPrice = Number.isFinite(breachPriceRaw) && breachPriceRaw > 0 ? breachPriceRaw : null;
        const priceDecimals = Math.max(
          getHypernovaDecimalPlaces(entryText),
          getHypernovaDecimalPlaces(markText),
          breachPrice ? getHypernovaDecimalPlaces(breachText) : 0
        );

        positions.push({
          symbol,
          side,
          entryPrice,
          markPrice: Number.isFinite(markPrice) && markPrice > 0 ? markPrice : null,
          breachPrice,
          sizeQty: Number.isFinite(sizeQty) && sizeQty > 0 ? sizeQty : null,
          notionalUsd: Number.isFinite(notionalUsd) && notionalUsd > 0 ? notionalUsd : null,
          unrealizedPnl: Number.isFinite(unrealizedPnl) ? unrealizedPnl : null,
          tpPrice,
          slPrice,
          priceDecimals
        });
      }
      return { foundTable: true, positions };
    } catch (e) {}
    return { foundTable: false, positions: [] };
  }

  function scrapeHypernovaOpenPositions() {
    return scrapeVenueOpenPositionsWithMeta().positions;
  }

  function ingestApiCapturedPositions(incoming) {
    if (!Array.isArray(incoming)) return;
    const normalized = [];
    const seen = new Set();
    for (const raw of incoming) {
      if (!raw || typeof raw !== 'object') continue;
      const sym = normalizeHypernovaBaseSymbol(raw.symbol || '');
      const entryPrice = Number(raw.entryPrice);
      if (!sym || !Number.isFinite(entryPrice) || entryPrice <= 0) continue;
      if (seen.has(sym)) continue;
      seen.add(sym);
      normalized.push({
        symbol: sym,
        side: raw.side === 'short' ? 'short' : 'long',
        entryPrice,
        markPrice: Number.isFinite(Number(raw.markPrice)) && Number(raw.markPrice) > 0 ? Number(raw.markPrice) : null,
        sizeQty: Number.isFinite(Number(raw.sizeQty)) && Number(raw.sizeQty) > 0 ? Number(raw.sizeQty) : null,
        notionalUsd: Number.isFinite(Number(raw.notionalUsd)) && Number(raw.notionalUsd) > 0 ? Number(raw.notionalUsd) : null,
        unrealizedPnl: Number.isFinite(Number(raw.unrealizedPnl)) ? Number(raw.unrealizedPnl) : null,
        tpPrice: Number.isFinite(Number(raw.tpPrice)) && Number(raw.tpPrice) > 0 ? Number(raw.tpPrice) : null,
        slPrice: Number.isFinite(Number(raw.slPrice)) && Number(raw.slPrice) > 0 ? Number(raw.slPrice) : null,
        breachPrice: Number.isFinite(Number(raw.breachPrice)) && Number(raw.breachPrice) > 0 ? Number(raw.breachPrice) : null,
        priceDecimals: Number.isInteger(raw.priceDecimals) ? raw.priceDecimals : null
      });
    }
    lastApiCapturedPositions = normalized;
    lastApiPositionsCapturedAt = Date.now();
    syncHypernovaPositionsToMainWorld(true);
  }

  let observedHypernovaPositionsBody = null;
  let hypernovaPositionsTableObserver = null;
  let hypernovaPositionsObserverTimer = null;

  function findLivePositionsObserveTarget() {
    try {
      if (getChartVisualsHostFirmId() === 'kalshipro') {
        const blotter = document.querySelector('div[data-perps-blotter="true"]');
        if (blotter) return blotter;
      }
      const found = findHypernovaPositionsTableAndRows();
      if (found && found.table) {
        return found.table.querySelector('tbody, [role="rowgroup"]:last-child') || found.table;
      }
      const mobileList = document.querySelector('[data-testid="positions-mobile-list"], .trade-positions-mobile-list, [data-testid="quick-trade-positions"]');
      if (mobileList) {
        const r = typeof mobileList.getBoundingClientRect === 'function' ? mobileList.getBoundingClientRect() : { width: 1, height: 1 };
        if (r.width > 0 && r.height > 0) return mobileList;
      }
    } catch (e) {}
    return null;
  }

  function ensureHypernovaPositionsTableObserver() {
    if (!isTopWindow || !isChartVisualsHost()) return;
    const target = findLivePositionsObserveTarget();
    if (!target) {
      if (hypernovaPositionsTableObserver) {
        try { hypernovaPositionsTableObserver.disconnect(); } catch (e) {}
        hypernovaPositionsTableObserver = null;
      }
      observedHypernovaPositionsBody = null;
      return;
    }
    if (target === observedHypernovaPositionsBody) return;
    try {
      if (hypernovaPositionsTableObserver) {
        hypernovaPositionsTableObserver.disconnect();
      }
      observedHypernovaPositionsBody = target;
      hypernovaPositionsTableObserver = new MutationObserver(() => {
        if (hypernovaPositionsObserverTimer) return;
        hypernovaPositionsObserverTimer = setTimeout(() => {
          hypernovaPositionsObserverTimer = null;
          syncHypernovaPositionsToMainWorld(false);
        }, 100);
      });
      hypernovaPositionsTableObserver.observe(target, { characterData: true, childList: true, subtree: true });
    } catch (e) {}
  }

  function getMergedVenueOpenPositions() {
    const domRes = scrapeVenueOpenPositionsWithMeta();
    if (domRes.foundTable) {
      ensureHypernovaPositionsTableObserver();
      // Positions panel IS currently visible — it is 100% authoritative!
      if (domRes.positions.length === 0) {
        // Explicitly flat (e.g. "No Open Positions"): clear ALL caches so entry/TP/SL boxes disappear immediately!
        lastKnownDomPositions = [];
        lastApiCapturedPositions = [];
        lastApiPositionsCapturedAt = 0;
        return [];
      }
      // Enrich DOM rows with TP/SL from API snapshot if the table didn't show a TP/SL column (e.g. MFP),
      // and prune any closed symbols out of lastApiCapturedPositions.
      const openSymSet = new Set(domRes.positions.map(p => p.symbol));
      lastApiCapturedPositions = lastApiCapturedPositions.filter(p => openSymSet.has(p.symbol));
      const apiBySym = new Map(lastApiCapturedPositions.map(p => [p.symbol, p]));
      const prevDomBySym = new Map((lastKnownDomPositions || []).filter(p => p && openSymSet.has(p.symbol)).map(p => [p.symbol, p]));
      const mergedDom = domRes.positions.map(p => {
        const api = apiBySym.get(p.symbol);
        const prev = prevDomBySym.get(p.symbol);
        const entryPrice = p.entryPrice !== null && p.entryPrice !== undefined
          ? p.entryPrice
          : ((api && api.entryPrice) || (prev && prev.entryPrice) || null);
        const markPrice = p.markPrice !== null && p.markPrice !== undefined
          ? p.markPrice
          : ((api && api.markPrice) || (prev && prev.markPrice) || null);
        const notionalUsd = p.notionalUsd !== null && p.notionalUsd !== undefined
          ? p.notionalUsd
          : ((api && api.notionalUsd) || (prev && prev.notionalUsd) || (p.sizeQty && entryPrice ? p.sizeQty * entryPrice : null));
        const priceDecimals = Number.isInteger(p.priceDecimals)
          ? p.priceDecimals
          : ((api && Number.isInteger(api.priceDecimals) ? api.priceDecimals : null) ??
             (prev && Number.isInteger(prev.priceDecimals) ? prev.priceDecimals : null));
        return {
          ...p,
          source: 'dom',
          entryPrice,
          markPrice,
          notionalUsd,
          priceDecimals,
          tpPrice: p.tpPrice !== null ? p.tpPrice : ((api && api.tpPrice) ?? (prev && prev.tpPrice) ?? null),
          slPrice: p.slPrice !== null ? p.slPrice : ((api && api.slPrice) ?? (prev && prev.slPrice) ?? null),
          breachPrice: p.breachPrice !== null ? p.breachPrice : ((api && api.breachPrice) ?? (prev && prev.breachPrice) ?? null)
        };
      });
      lastKnownDomPositions = mergedDom;
      return mergedDom;
    }
    ensureHypernovaPositionsTableObserver();
    // Positions table is NOT currently visible (e.g. user is viewing `Accounts`, `Open Orders`, or `History` tab).
    // Check if the `Positions (0)` tab badge explicitly says 0, OR if an empty state is visible!
    const posTab = Array.from(document.querySelectorAll('[role="tablist"] [role="tab"], .trade-tabs-list [role="tab"]'))
      .find(t => /^positions\b/i.test((t.innerText || t.textContent || '').trim()));
    if (posTab) {
      const tabTxt = (posTab.innerText || posTab.textContent || '').trim();
      const m = tabTxt.match(/\bpositions\s*\(?\s*(\d+)\s*\)?/i);
      if ((m && Number(m[1]) === 0) || (getChartVisualsHostFirmId() === 'hypernova' && /^positions$/i.test(tabTxt))) {
        // On Hypernova, the tab says "Positions (1)" when open and bare "Positions" when 0 open positions!
        lastKnownDomPositions = [];
        lastApiCapturedPositions = [];
        lastApiPositionsCapturedAt = 0;
        return [];
      }
    }

    let fallback = (lastApiCapturedPositions.length > 0 && (Date.now() - lastApiPositionsCapturedAt < 120000))
      ? lastApiCapturedPositions
      : lastKnownDomPositions;

    // If the right-hand order ticket explicitly says "Current Position: FLAT", strip the active chart symbol immediately!
    if (fallback.length > 0 && isCurrentChartOrderTicketFlat()) {
      const activeSym = getCurrentTopChartSymbolForFlatCheck();
      if (activeSym) {
        fallback = fallback.filter(p => p.symbol !== activeSym);
        lastKnownDomPositions = lastKnownDomPositions.filter(p => p.symbol !== activeSym);
        lastApiCapturedPositions = lastApiCapturedPositions.filter(p => p.symbol !== activeSym);
      }
    }
    return fallback.map(p => ({ ...p, source: 'cached' }));
  }

  let observedHypernovaBreachEl = null;
  let hypernovaBreachObserver = null;
  let hypernovaBreachSyncDebounce = null;

  function findHypernovaOrderTicketBreachEl() {
    if (getChartVisualsHostFirmId() !== 'hypernova') return null;
    try {
      const candidates = [];
      const directAll = Array.from(document.querySelectorAll('[data-testid="order-details-breach-price"]'));
      for (const el of directAll) candidates.push(el);
      if (candidates.length === 0) {
        const rows = document.querySelectorAll('.order-info-row');
        for (const row of rows) {
          const label = row.querySelector('.order-info-label');
          if (label && /^\s*breach\s*price\s*$/i.test(label.textContent || '')) {
            const valEl = row.querySelector('.order-info-value');
            if (valEl) candidates.push(valEl);
          }
        }
      }
      if (candidates.length === 0) return null;
      const isVisible = (el) => {
        if (!el || typeof el.getBoundingClientRect !== 'function') return true;
        const r = el.getBoundingClientRect();
        return r.width > 0 && r.height > 0;
      };
      const hasNumericPrice = (el) => {
        const txt = (el.innerText || el.textContent || '').trim();
        if (!txt || /n\/a|^[-—]+$/i.test(txt)) return false;
        const v = Math.abs(parseHypernovaNumber(txt));
        return Number.isFinite(v) && v > 0;
      };
      // Prefer a visible element with an active numeric price (handles desktop + mobile order drawer copies cleanly)
      return candidates.find(el => isVisible(el) && hasNumericPrice(el)) ||
        candidates.find(el => hasNumericPrice(el)) ||
        candidates.find(el => isVisible(el)) ||
        candidates[0];
    } catch (e) {}
    return null;
  }

  function ensureHypernovaBreachObserver() {
    if (!isTopWindow || getChartVisualsHostFirmId() !== 'hypernova') return;
    const el = findHypernovaOrderTicketBreachEl();
    if (!el) {
      if (observedHypernovaBreachEl && !observedHypernovaBreachEl.isConnected) {
        if (hypernovaBreachObserver) {
          try { hypernovaBreachObserver.disconnect(); } catch (e) {}
          hypernovaBreachObserver = null;
        }
        observedHypernovaBreachEl = null;
      }
      return;
    }
    if (el === observedHypernovaBreachEl && el.isConnected) return;
    try {
      if (hypernovaBreachObserver) {
        hypernovaBreachObserver.disconnect();
      }
      observedHypernovaBreachEl = el;
      hypernovaBreachObserver = new MutationObserver(() => {
        if (hypernovaBreachSyncDebounce) clearTimeout(hypernovaBreachSyncDebounce);
        hypernovaBreachSyncDebounce = setTimeout(() => {
          hypernovaBreachSyncDebounce = null;
          syncHypernovaPositionsToMainWorld(false);
        }, 40);
      });
      hypernovaBreachObserver.observe(el, { characterData: true, childList: true, subtree: true });
    } catch (e) {}
  }

  function scrapeHypernovaOrderTicketBreachPrice() {
    if (getChartVisualsHostFirmId() !== 'hypernova') return null;
    ensureHypernovaBreachObserver();
    try {
      const valEl = findHypernovaOrderTicketBreachEl();
      if (!valEl) return null;
      const rawText = (valEl.innerText || valEl.textContent || '').trim();
      if (!rawText || /n\/a|^[-—]+$/i.test(rawText)) return null;
      const price = Math.abs(parseHypernovaNumber(rawText));
      if (!Number.isFinite(price) || price <= 0) return null;
      const decimals = getHypernovaDecimalPlaces(rawText);
      const symbol = getCurrentTopChartSymbolForFlatCheck() || '';
      return {
        price,
        rawText,
        decimals,
        symbol,
        source: 'order-ticket'
      };
    } catch (e) {}
    return null;
  }

  function syncHypernovaPositionsToMainWorld(force = false) {
    if (!isTopWindow || !isChartVisualsHost()) return;
    hypernovaSyncTickCount++;
    const positions = getMergedVenueOpenPositions();
    const orderTicketBreach = scrapeHypernovaOrderTicketBreachPrice();
    const sig = JSON.stringify({ positions, orderTicketBreach });
    // Periodically rebroadcast every 4th tick (~3.2s) so newly recreated TradingView iframes always stay in sync (including flat!)
    const periodicRefresh = (hypernovaSyncTickCount % 4 === 0);
    if (!force && !periodicRefresh && sig === lastHypernovaPositionsSig) return;
    lastHypernovaPositionsSig = sig;
    postToMainWorlds({
      type: 'VEST_TV_HYPERNOVA_POSITIONS_UPDATE',
      payload: { positions, orderTicketBreach }
    });
  }

  function findHypernovaPositionRowBySymbol(symbol) {
    if (getChartVisualsHostFirmId() === 'kalshipro') {
      return findKalshiProPositionRowBySymbol(symbol);
    }
    const targetSym = normalizeHypernovaBaseSymbol(symbol);
    const found = findHypernovaPositionsTableAndRows();
    if (!found || !found.rows.length) {
      // Fallback: Hypernova mobile positions cards (`[data-testid^="positions-mobile-row-"]`)
      const mobileRows = Array.from(document.querySelectorAll('[data-testid^="positions-mobile-row-"]')).filter(r => {
        const rr = typeof r.getBoundingClientRect === 'function' ? r.getBoundingClientRect() : { width: 1, height: 1 };
        return rr.width > 0 && rr.height > 0;
      });
      for (const row of mobileRows) {
        const symTextEl = row.querySelector('[data-testid="symbol-text"]') || row.querySelector('[data-testid$="-coin"]');
        const symText = symTextEl ? (symTextEl.innerText || symTextEl.textContent || '').replace(/^market\b/i, '').trim() : '';
        const rowSym = extractSymbolFromCellText(symText);
        if (!targetSym || rowSym === targetSym) {
          const entryEl = row.querySelector('[data-testid$="-entry"] .trade-positions-mobile-detail-value') || row.querySelector('[data-testid$="-entry"]');
          const markEl = row.querySelector('[data-testid$="-mark"] .trade-positions-mobile-detail-value') || row.querySelector('[data-testid$="-mark"]');
          const entryText = entryEl ? (entryEl.innerText || entryEl.textContent || '') : '';
          const markText = markEl ? (markEl.innerText || markEl.textContent || '') : '';
          const priceDecimals = (entryText || markText)
            ? Math.max(getHypernovaDecimalPlaces(entryText), getHypernovaDecimalPlaces(markText))
            : null;
          const rowButtons = Array.from(row.querySelectorAll('button, [role="button"]'));
          const mobileExpandBtn = row.querySelector('[data-testid^="positions-mobile-toggle-"]') ||
            row.querySelector('.trade-positions-mobile-chevron-btn') || null;
          const tpSlTrigger =
            row.querySelector('[data-testid="position-tpsl"]') ||
            row.querySelector('.trade-positions-mobile-tpsl-chip') ||
            rowButtons.find(b => /tp\s*\/?\s*sl|take\s*profit|stop\s*loss/i.test(`${b.innerText || b.textContent || ''} ${b.getAttribute('aria-label') || ''}`)) ||
            null;
          const closeTrigger =
            row.querySelector('[data-testid="close-position-menu-trigger"]') ||
            rowButtons.find(b => {
              const t = (b.innerText || b.textContent || '').trim();
              const aria = (b.getAttribute('aria-label') || b.getAttribute('title') || '').trim();
              return /^(market|close|market\s+close|exit)$/i.test(t) || /close\s*position/i.test(aria);
            }) ||
            null;
          return {
            row,
            cells: [],
            headers: [],
            idxTpSl: -1,
            tpSlTrigger,
            closeTrigger,
            mobileExpandBtn,
            priceDecimals,
            existingTpPrice: null,
            existingSlPrice: null,
            isKalshiPro: false,
            isMobileCard: true
          };
        }
      }
      return null;
    }
    const { headers, rows } = found;
    const idxSym = Math.max(0, headers.findIndex(h => /market|symbol|coin|pair|asset|contract|instrument|ticker/.test(h)));
    const idxEntry = headers.findIndex(h => /entry|open price|avg/.test(h));
    const idxMark = headers.findIndex(h => /mark|mid|oracle|index|last|current/.test(h));
    const idxTpSl = headers.findIndex(h => /tp\s*\/?\s*sl|take\s*profit|stop\s*loss/.test(h));
    for (const row of rows) {
      if (row.querySelector('[data-slot="empty"]')) continue;
      const cells = Array.from(row.querySelectorAll('td, [role="cell"]'));
      if (cells.length < 3) continue;
      const symTextEl = row.querySelector('[data-testid="symbol-text"]');
      const symText = symTextEl
        ? (symTextEl.innerText || symTextEl.textContent || '').trim()
        : (cells[idxSym] ? (cells[idxSym].innerText || cells[idxSym].textContent) : (row.innerText || '')).trim();
      const rowSym = extractSymbolFromCellText(symText);
      if (!targetSym || rowSym === targetSym) {
        const entryTd = row.querySelector('td[data-testid$="-entry"]') || (idxEntry >= 0 ? cells[idxEntry] : null);
        const markTd = row.querySelector('td[data-testid$="-mark"]') || (idxMark >= 0 ? cells[idxMark] : null);
        const entryText = entryTd ? (entryTd.innerText || entryTd.textContent || '') : '';
        const markText = markTd ? (markTd.innerText || markTd.textContent || '') : '';
        const priceDecimals = (entryText || markText)
          ? Math.max(getHypernovaDecimalPlaces(entryText), getHypernovaDecimalPlaces(markText))
          : null;
        // Exact Hypernova clickable trigger is `<span class="trade-positions-tpsl-cell" data-testid="position-tpsl">`;
        // on My Funded Perps & Kalshi Pro, also match explicit TP/SL buttons or edit/pencil action buttons in the row
        // (NEVER click an <svg> child directly because SVGElement lacks `.click()`!)
        const rowButtons = Array.from(row.querySelectorAll('button, [role="button"]'));
        const tpSlTrigger =
          row.querySelector('[data-testid="position-tpsl"]') ||
          row.querySelector('.trade-positions-tpsl-cell') ||
          (idxTpSl >= 0 && cells[idxTpSl]
            ? (cells[idxTpSl].querySelector('button, [role="button"], span') || cells[idxTpSl])
            : null) ||
          rowButtons.find(b => {
            const t = `${b.innerText || b.textContent || ''} ${b.getAttribute('aria-label') || ''} ${b.getAttribute('title') || ''}`;
            return /tp\s*\/?\s*sl|take\s*profit|stop\s*loss|edit.*tp|set\s*tp/i.test(t);
          }) ||
          rowButtons.find(b => Boolean(b.querySelector('svg.lucide-pencil, svg.lucide-pen, svg.lucide-edit, svg[class*="pencil" i], svg[class*="edit" i]'))) ||
          null;
        const closeTrigger =
          row.querySelector('[data-testid="close-position-menu-trigger"]') ||
          rowButtons.find(b => {
            const t = (b.innerText || b.textContent || '').trim();
            const aria = (b.getAttribute('aria-label') || b.getAttribute('title') || '').trim();
            return /^(market|close|market\s+close|exit|×|x)$/i.test(t) || /close|exit/i.test(aria);
          }) ||
          null;
        return { row, cells, headers, idxTpSl, tpSlTrigger, closeTrigger, priceDecimals, existingTpPrice: null, existingSlPrice: null, isKalshiPro: false };
      }
    }
    return null;
  }

  function findHypernovaTpSlDialog() {
    // Fast-path 1: Hypernova exact `[role="dialog"][data-testid="tpsl"]`
    const exactHn = document.querySelector('[role="dialog"][data-testid="tpsl"]');
    if (exactHn) {
      const st = exactHn.getAttribute('data-state');
      const r = exactHn.getBoundingClientRect();
      if (st !== 'closed' && r.width > 120 && r.height > 80) return exactHn;
    }
    // Fast-path 2: Kalshi Pro exact `[role="dialog"][aria-labelledby="perps-tpsl-title"]`
    const exactKalshi = document.querySelector('[role="dialog"][aria-labelledby="perps-tpsl-title"]') ||
      (document.getElementById('perps-tpsl-title') ? document.getElementById('perps-tpsl-title').closest('[role="dialog"]') : null);
    if (exactKalshi) {
      const r = exactKalshi.getBoundingClientRect();
      if (r.width > 120 && r.height > 80) return exactKalshi;
    }
    return Array.from(document.querySelectorAll('[role="dialog"], [data-slot="dialog-content"], [data-slot="popover-content"], [data-slot="sheet-content"], [class*="tpsl-modal" i], [class*="modal" i]')).find(d => {
      if (d.id && d.id.startsWith('vest-')) return false;
      if (d.getAttribute('data-state') === 'closed') return false;
      const r = d.getBoundingClientRect();
      if (r.width <= 160 || r.height <= 90) return false;
      return Boolean(
        d.querySelector('[data-testid="tpsl-tp-price-input"], [data-testid="tpsl-sl-price-input"], [data-testid="tpsl-confirm"], #perps-tpsl-tp-price, #perps-tpsl-sl-price, #take-profit-price, #stop-loss-price') ||
        /tp\s*\/\s*sl|take\s*profit|stop\s*loss/i.test(d.innerText || '')
      );
    }) || null;
  }

  function findTpSlInputInRoot(root, kind) {
    if (!root) return null;
    const wantTp = kind === 'tp';
    // Fast-path: Hypernova (`tpsl-*-price-input`), Kalshi Pro (`#perps-tpsl-*-price`), My Funded Perps (`#take-profit-price` / `#stop-loss-price`)
    const exact = root.querySelector(
      wantTp
        ? '[data-testid="tpsl-tp-price-input"], #perps-tpsl-tp-price, #take-profit-price'
        : '[data-testid="tpsl-sl-price-input"], #perps-tpsl-sl-price, #stop-loss-price'
    );
    if (exact && !exact.disabled) return exact;

    const matchRe = wantTp ? /take\s*profit|\btp\b/i : /stop\s*loss|\bsl\b/i;
    const excludeRe = wantTp ? /stop\s*loss|\bsl\b|gain|percent|roi|roe|%/i : /take\s*profit|\btp\b|loss\s*%|gain|percent|roi|roe|%/i;
    const inputs = Array.from(root.querySelectorAll('input[type="text"], input[type="number"], input:not([type])')).filter(inp => {
      const r = inp.getBoundingClientRect();
      return r.width > 20 && r.height > 12 && !inp.disabled;
    });
    for (const inp of inputs) {
      const attrs = `${inp.placeholder || ''} ${inp.name || ''} ${inp.id || ''} ${inp.getAttribute('aria-label') || ''} ${inp.getAttribute('data-testid') || ''}`;
      if (matchRe.test(attrs) && !excludeRe.test(attrs) && !/loss$|percent$/i.test(inp.id || '')) return inp;
      let parent = inp.parentElement;
      for (let up = 0; up < 3 && parent && parent !== root; up++) {
        const txt = (parent.innerText || parent.textContent || '').replace(/\s+/g, ' ').trim();
        if (txt.length <= 60 && matchRe.test(txt) && !excludeRe.test(txt)) return inp;
        parent = parent.parentElement;
      }
    }
    return null;
  }

  function extractHypernovaDialogErrorText(dialog) {
    if (!dialog) return '';
    try {
      const errEls = Array.from(dialog.querySelectorAll('[role="alert"], [class*="error" i], [class*="warning" i], [data-testid*="error" i]'));
      for (const el of errEls) {
        const txt = (el.innerText || el.textContent || '').replace(/\s+/g, ' ').trim();
        if (txt && txt.length <= 160) return txt;
      }
    } catch (e) {}
    return '';
  }

  let hypernovaTpSlActionInFlight = false;

  async function submitHypernovaTpSlModalValue({ symbol, kind, valueStr, isBe = false, isClear = false, pnlStr = '', isAutoTrail = false, trailReason = '' }) {
    if (hypernovaTpSlActionInFlight) return;
    // Safety guard: Auto-Trail never steals focus if user has Cortex Settings or another exchange dialog open
    if (isAutoTrail) {
      const cortexModalOpen = Boolean(document.getElementById('vest-studio-settings-dialog') || document.getElementById('vest-template-manager-dialog'));
      if (cortexModalOpen) {
        postToMainWorlds({
          type: 'VEST_TV_HYPERNOVA_TP_SL_RESULT',
          payload: { ok: false, symbol, type: kind, isAutoTrail: true, reason: 'busy_modal' }
        });
        return;
      }
    }
    hypernovaTpSlActionInFlight = true;
    const venueLabel = getChartVisualsHostDisplayName();
    const notifyResult = (ok, extra = {}) => {
      postToMainWorlds({
        type: 'VEST_TV_HYPERNOVA_TP_SL_RESULT',
        payload: { ok, symbol, type: kind, isAutoTrail: Boolean(isAutoTrail), ...extra }
      });
    };

    try {
      await ensureHypernovaPositionsTabActive();
      let rowInfo = findHypernovaPositionRowBySymbol(symbol);
      if (rowInfo && rowInfo.isMobileCard && !rowInfo.tpSlTrigger && rowInfo.mobileExpandBtn) {
        dispatchHypernovaClick(rowInfo.mobileExpandBtn);
        rowInfo = await waitForHypernovaCondition(() => {
          const next = findHypernovaPositionRowBySymbol(symbol);
          return next && next.tpSlTrigger ? next : null;
        }, 650, 40) || rowInfo;
      }
      const formatted = isClear ? '' : (typeof valueStr === 'string' ? valueStr : formatHypernovaOrderPrice(valueStr, rowInfo ? rowInfo.priceDecimals : null));

      let dialog = findHypernovaTpSlDialog();
      if (!dialog) {
        if (!rowInfo || !rowInfo.tpSlTrigger) {
          showToast(`Could not locate open ${symbol || ''} position TP/SL button on ${venueLabel}`);
          notifyResult(false, { reason: 'position_row_not_found' });
          return;
        }
        dispatchHypernovaClick(rowInfo.tpSlTrigger);
        dialog = await waitForHypernovaCondition(() => findHypernovaTpSlDialog(), 1800, 40);
      }

      if (!dialog) {
        showToast(`Could not open ${venueLabel} TP/SL dialog for ${symbol || 'position'}`);
        notifyResult(false, { reason: 'dialog_not_opened' });
        return;
      }

      const input = await waitForHypernovaCondition(() => findTpSlInputInRoot(dialog, kind), 1000, 40);
      if (!input) {
        showToast(`Could not find ${kind.toUpperCase()} price input in ${venueLabel} dialog`);
        notifyResult(false, { reason: 'input_not_found' });
        return;
      }

      // Kalshi Pro auto-fills suggested +15%/-15% TP & SL defaults when opening Edit TP/SL on a position with no TP/SL set.
      // Clear the untouched opposite field if that position did NOT previously have one so we ONLY submit what the user dragged!
      const isKalshiModal = Boolean(dialog.querySelector('#perps-tpsl-tp-price, #perps-tpsl-sl-price') || (rowInfo && rowInfo.isKalshiPro));
      if (isKalshiModal) {
        const otherKind = kind === 'tp' ? 'sl' : 'tp';
        const otherInput = findTpSlInputInRoot(dialog, otherKind);
        const hadOther = otherKind === 'tp'
          ? Boolean(rowInfo && rowInfo.existingTpPrice)
          : Boolean(rowInfo && rowInfo.existingSlPrice);
        if (otherInput && !hadOther && String(otherInput.value || '').trim() !== '') {
          setReactNativeInputValue(otherInput, '');
        }
        // If clearing the ONLY active TP/SL on Kalshi Pro, click Kalshi's dedicated `Delete` button!
        if (isClear && !hadOther) {
          const deleteBtn = Array.from(dialog.querySelectorAll('button')).find(b => /^delete$/i.test((b.innerText || b.textContent || '').trim()) && !b.disabled);
          if (deleteBtn) {
            dispatchHypernovaClick(deleteBtn);
            const closedAfterDelete = await waitForHypernovaCondition(() => !findHypernovaTpSlDialog(), 3000, 60);
            if (closedAfterDelete) {
              showToast(`Cleared ${venueLabel} ${kind.toUpperCase()} order`);
              notifyResult(true, { price: null });
              setTimeout(() => syncHypernovaPositionsToMainWorld(true), 300);
              setTimeout(() => syncHypernovaPositionsToMainWorld(true), 1000);
              return;
            }
          }
        }
      }

      setReactNativeInputValue(input, formatted);

      // Wait for React state & validation to enable the modal Confirm/Submit button
      const confirmBtn = await waitForHypernovaCondition(() => {
        const btn = dialog.querySelector('[data-testid="tpsl-confirm"]') ||
          dialog.querySelector('button[type="submit"]') ||
          Array.from(dialog.querySelectorAll('button')).find(b => /^(confirm|save|update|apply|set|submit|place)/i.test((b.innerText || b.textContent || '').trim()));
        return btn && !btn.disabled ? btn : null;
      }, 800, 40);

      if (!confirmBtn) {
        const errTxt = extractHypernovaDialogErrorText(dialog);
        const cancelBtn = dialog.querySelector('[data-testid="tpsl-cancel"]') ||
          dialog.querySelector('button[aria-label="Close TP/SL modal"]') ||
          dialog.querySelector('.dialog-close-btn') ||
          Array.from(dialog.querySelectorAll('button')).find(b => /^(cancel|close)$/i.test((b.innerText || b.textContent || '').trim()));
        if (cancelBtn) dispatchHypernovaClick(cancelBtn);
        showToast(
          errTxt
            ? `${venueLabel} ${kind.toUpperCase()} rejected: ${errTxt}`
            : `${venueLabel} rejected ${kind.toUpperCase()} at $${formatted} (must be on valid side of Mark Price)`
        );
        notifyResult(false, { reason: 'confirm_disabled', error: errTxt });
        return;
      }

      dispatchHypernovaClick(confirmBtn);

      // Wait for the exchange to submit the order & close the dialog
      const closed = await waitForHypernovaCondition(() => {
        const openDialog = findHypernovaTpSlDialog();
        return !openDialog;
      }, 3500, 60);

      if (!closed) {
        const errTxt = extractHypernovaDialogErrorText(dialog);
        showToast(
          errTxt
            ? `${venueLabel} ${kind.toUpperCase()} error: ${errTxt}`
            : `${venueLabel} TP/SL modal stayed open — verify order in dialog`
        );
        notifyResult(false, { reason: 'dialog_stayed_open', error: errTxt });
        return;
      }

      if (isClear) {
        showToast(`Cleared ${venueLabel} ${kind.toUpperCase()} order`);
      } else if (isAutoTrail) {
        const suffix = trailReason ? ` · ${trailReason}` : '';
        showToast(`${venueLabel} Auto-Trail SL → $${formatted}${pnlStr}${suffix}`);
      } else {
        showToast(
          isBe
            ? `${venueLabel} Breakeven SL submitted ($${formatted})`
            : `${venueLabel} ${kind.toUpperCase()} submitted at $${formatted}${pnlStr}`
        );
      }

      notifyResult(true, { price: isClear ? null : Number(formatted) });
      setTimeout(() => syncHypernovaPositionsToMainWorld(true), 300);
      setTimeout(() => syncHypernovaPositionsToMainWorld(true), 900);
      setTimeout(() => syncHypernovaPositionsToMainWorld(true), 2000);
    } catch (e) {
      notifyResult(false, { reason: 'exception' });
    } finally {
      hypernovaTpSlActionInFlight = false;
    }
  }

  function executeHypernovaTpSlAction(payload) {
    const kind = payload.type === 'tp' ? 'tp' : 'sl';
    const isBe = payload.type === 'be';
    const isAutoTrail = Boolean(payload.isAutoTrail);
    const trailReason = typeof payload.trailReason === 'string' ? payload.trailReason : '';
    const price = Number(payload.price);
    const symbol = payload.symbol || '';
    if (!Number.isFinite(price) || price <= 0) return;
    const pnlStr = typeof payload.pnlText === 'string' && payload.pnlText ? ` (${payload.pnlText})` : '';
    submitHypernovaTpSlModalValue({ symbol, kind, valueStr: price, isBe, isClear: false, pnlStr, isAutoTrail, trailReason });
  }

  function executeHypernovaClearTpSlAction(payload) {
    const kind = payload.type === 'tp' ? 'tp' : 'sl';
    const symbol = payload.symbol || '';
    submitHypernovaTpSlModalValue({ symbol, kind, valueStr: '', isBe: false, isClear: true });
  }

  async function executeHypernovaClosePositionAction(payload) {
    const symbol = payload.symbol || '';
    const venueLabel = getChartVisualsHostDisplayName();
    await ensureHypernovaPositionsTabActive();
    let rowInfo = findHypernovaPositionRowBySymbol(symbol);
    if (rowInfo && rowInfo.isMobileCard && !rowInfo.closeTrigger && rowInfo.mobileExpandBtn) {
      dispatchHypernovaClick(rowInfo.mobileExpandBtn);
      rowInfo = await waitForHypernovaCondition(() => {
        const next = findHypernovaPositionRowBySymbol(symbol);
        return next && next.closeTrigger ? next : null;
      }, 650, 40) || rowInfo;
    }
    if (rowInfo && rowInfo.closeTrigger) {
      dispatchHypernovaClick(rowInfo.closeTrigger);
      // Support Radix/Base UI Close dropdown menus (e.g. Hypernova's `close-position-menu-trigger`) -> Market Close
      const marketItem = await waitForHypernovaCondition(() => {
        const items = Array.from(document.querySelectorAll('[role="menuitem"], [data-slot="dropdown-menu-item"]'));
        return items.find(it => /market/i.test((it.innerText || it.textContent || '').trim())) || null;
      }, 600, 40);
      if (marketItem) {
        dispatchHypernovaClick(marketItem);
        showToast(`Triggered ${venueLabel} Market Close for ${symbol || 'active trade'}`);
      } else {
        showToast(`Triggered ${venueLabel} Close for ${symbol || 'active trade'}`);
      }
      setTimeout(() => syncHypernovaPositionsToMainWorld(true), 600);
      setTimeout(() => syncHypernovaPositionsToMainWorld(true), 1500);
      return;
    }
    showToast(`Use ${venueLabel}'s Close button to exit ${symbol || 'position'}`);
  }

  if (isTopWindow && isChartVisualsHost() && !hypernovaPositionsTimer) {
    hypernovaPositionsTimer = setInterval(() => {
      if (!isExtensionValid()) {
        clearInterval(hypernovaPositionsTimer);
        hypernovaPositionsTimer = null;
        return;
      }
      syncHypernovaPositionsToMainWorld(false);
    }, 800);
  }

  function getHypernovaChartLeftInset() {
    if (!isHypernovaHost()) return 0;
    try {
      // 1. Prefer the TradingView chart iframe or chart container left edge (when positioned right of the icon sidebar)
      const chartCandidates = Array.from(document.querySelectorAll('iframe, [class*="chart"], [id*="chart"], [class*="tradingview"]'));
      for (let i = 0; i < chartCandidates.length; i++) {
        const r = chartCandidates[i].getBoundingClientRect();
        if (r.width >= 320 && r.height >= 240 && r.left >= 32 && r.left <= 120) {
          return Math.round(r.left);
        }
      }
      // 2. Fallback to the ticker/market row left edge
      const market = typeof findMarketSelectorElement === 'function' ? findMarketSelectorElement() : null;
      if (market && market.rowEl) {
        const mr = market.rowEl.getBoundingClientRect();
        if (mr.left >= 32 && mr.left <= 120) {
          return Math.round(mr.left);
        }
      }
      // 3. Fallback to the collapsed left vertical navigation rail width (cap at <= 96px so expanding pull-out drawer glides over cleanly)
      const sidebars = Array.from(document.querySelectorAll('aside, nav, [class*="sidebar"], [class*="Sidebar"]'));
      for (let i = 0; i < sidebars.length; i++) {
        const r = sidebars[i].getBoundingClientRect();
        if (r.left <= 4 && r.height >= window.innerHeight * 0.5 && r.width >= 36 && r.width <= 96) {
          return Math.round(r.right);
        }
      }
    } catch (e) {}
    return 48;
  }

  function findHypernovaInflowMountPoint() {
    if (!isHypernovaHost()) return null;
    try {
      // 1. Find Hypernova's top header inside the main right-hand column (e.g. "Active Assessment" / <header>)
      const headerCandidates = Array.from(document.querySelectorAll('header, [role="banner"], div')).filter(el => {
        if (!el || el.id === CORTEX_TOP_BAR_ID || el.id.startsWith('vest-') || el.closest('#' + CORTEX_TOP_BAR_ID)) return false;
        const r = el.getBoundingClientRect();
        if (r.top < -4 || r.top > 12 || r.height < 30 || r.height > 80 || r.width < window.innerWidth * 0.5) return false;
        const parent = el.parentElement;
        if (!parent || parent === document.body) return false;
        // Must have a sibling below it (the trading content / chart area)
        let sib = el.nextElementSibling;
        while (sib && sib.id === CORTEX_TOP_BAR_ID) sib = sib.nextElementSibling;
        if (!sib) return false;
        const sr = sib.getBoundingClientRect();
        return sr.height >= 240 && sr.width >= window.innerWidth * 0.5;
      });

      // Prefer semantic <header> or the deepest direct header bar right above the main trading workspace
      headerCandidates.sort((a, b) => {
        const aScore = (a.tagName === 'HEADER' ? 10 : 0) + (a.getBoundingClientRect().left >= 32 ? 5 : 0);
        const bScore = (b.tagName === 'HEADER' ? 10 : 0) + (b.getBoundingClientRect().left >= 32 ? 5 : 0);
        if (bScore !== aScore) return bScore - aScore;
        return b.getBoundingClientRect().left - a.getBoundingClientRect().left;
      });

      if (headerCandidates.length > 0) {
        const headerEl = headerCandidates[0];
        let afterEl = headerEl.nextElementSibling;
        while (afterEl && afterEl.id === CORTEX_TOP_BAR_ID) afterEl = afterEl.nextElementSibling;
        if (headerEl.parentElement && afterEl) {
          return { parent: headerEl.parentElement, beforeEl: afterEl, headerEl };
        }
      }

      // 2. Fallback: locate <main> or the ticker row's top-level workspace container inside a flex-column parent
      const mainEl = document.querySelector('main');
      if (mainEl && mainEl.parentElement && mainEl.parentElement !== document.body) {
        const mr = mainEl.getBoundingClientRect();
        if (mr.height >= 240 && mr.width >= window.innerWidth * 0.5) {
          return { parent: mainEl.parentElement, beforeEl: mainEl, headerEl: mainEl.previousElementSibling };
        }
      }
    } catch (e) {}
    return null;
  }

  function findChartBottomDockMountPoint() {
    try {
      // 1. Prefer the TradingView chart iframe itself
      let chartEl = null;
      const iframes = Array.from(document.querySelectorAll('iframe'));
      let bestArea = 0;
      for (let i = 0; i < iframes.length; i++) {
        const r = iframes[i].getBoundingClientRect();
        const area = r.width * r.height;
        if (r.width >= 320 && r.height >= 200 && area > bestArea) {
          bestArea = area;
          chartEl = iframes[i];
        }
      }
      // 2. Fallback to a non-iframe chart container if the platform renders TradingView directly in the top document
      if (!chartEl) {
        const chartDivs = Array.from(document.querySelectorAll('[id*="tv_chart_container"], [class*="chart-container"], .layout__area--center'));
        for (let i = 0; i < chartDivs.length; i++) {
          const r = chartDivs[i].getBoundingClientRect();
          const area = r.width * r.height;
          if (r.width >= 320 && r.height >= 200 && area > bestArea) {
            bestArea = area;
            chartEl = chartDivs[i];
          }
        }
      }
      // 3. Fallback to the largest visible chart <canvas> (e.g. Tailwind/React canvas charts without iframe or chart-container class)
      if (!chartEl) {
        const canvases = Array.from(document.querySelectorAll('canvas'));
        let bestCanvas = null;
        for (let i = 0; i < canvases.length; i++) {
          const r = canvases[i].getBoundingClientRect();
          const area = r.width * r.height;
          if (r.width >= 320 && r.height >= 200 && area > bestArea) {
            bestArea = area;
            bestCanvas = canvases[i];
          }
        }
        if (bestCanvas) {
          const cr = bestCanvas.getBoundingClientRect();
          let wrap = bestCanvas;
          let up = 0;
          while (wrap.parentElement && wrap.parentElement !== document.body && up < 5) {
            const pr = wrap.parentElement.getBoundingClientRect();
            if (pr.width <= cr.width + 120 && pr.height <= cr.height + 80) {
              wrap = wrap.parentElement;
              up++;
            } else {
              break;
            }
          }
          chartEl = wrap;
        }
      }
      if (!chartEl || !chartEl.parentElement) return null;

      // Walk up wrapper divs (up to 7 levels) until targetEl is IN-FLOW (never position:absolute/fixed,
      // which would cause a relative bottom dock sibling to stack at y=0 covering the top of the chart!)
      // and lives inside a flex-column (or vertical block) container.
      // CRITICAL: Never walk past a resizable panel ([data-panel]) or mount into a splitter group
      // ([data-panel-group] / sibling [role="separator"]), otherwise the splitter snaps the chart back!
      const isResizablePanelEl = (el) => {
        if (!el || typeof el.hasAttribute !== 'function') return false;
        return (
          el.hasAttribute('data-panel') ||
          el.hasAttribute('data-panel-id') ||
          el.hasAttribute('data-panel-size')
        );
      };
      const isResizableGroupEl = (el) => {
        if (!el || typeof el.hasAttribute !== 'function') return false;
        if (el.hasAttribute('data-panel-group') || el.hasAttribute('data-panel-group-id')) return true;
        try {
          return Array.from(el.children || []).some(c =>
            c && typeof c.hasAttribute === 'function' && (
              c.hasAttribute('data-panel-resize-handle-id') ||
              c.hasAttribute('data-resize-handle') ||
              c.getAttribute('role') === 'separator'
            )
          );
        } catch (e) {
          return false;
        }
      };

      let targetEl = chartEl;
      let depth = 0;
      let fallbackInFlow = null;
      while (targetEl.parentElement && targetEl.parentElement !== document.body && depth < 7) {
        const parent = targetEl.parentElement;
        if (isResizablePanelEl(targetEl) || isResizableGroupEl(parent)) {
          break;
        }
        const tStyle = window.getComputedStyle(targetEl);
        const pStyle = window.getComputedStyle(parent);
        const isOutOfFlow = tStyle && (tStyle.position === 'absolute' || tStyle.position === 'fixed');
        if (!isOutOfFlow) {
          const isFlex = Boolean(pStyle && pStyle.display && pStyle.display.includes('flex'));
          const isFlexCol = isFlex && pStyle.flexDirection === 'column';
          const isFlexRow = isFlex && !isFlexCol;
          if (isFlexCol) {
            return { parent, afterEl: targetEl, chartEl };
          }
          if (!isFlexRow) {
            if (!fallbackInFlow) {
              fallbackInFlow = { parent, afterEl: targetEl, chartEl };
            }
            const visibleSibs = Array.from(parent.children).filter(c => {
              if (!c || c === targetEl || c.id === CORTEX_TOP_BAR_ID) return false;
              const cs = window.getComputedStyle(c);
              if (cs && (cs.position === 'absolute' || cs.position === 'fixed')) return false;
              return c.getBoundingClientRect().height > 10;
            });
            if (visibleSibs.length > 0) {
              return { parent, afterEl: targetEl, chartEl };
            }
          }
        }
        targetEl = parent;
        depth++;
      }
      if (fallbackInFlow) return fallbackInFlow;
      if (targetEl.parentElement && targetEl.parentElement !== document.body && !isResizableGroupEl(targetEl.parentElement)) {
        return { parent: targetEl.parentElement, afterEl: targetEl, chartEl };
      }
      if (chartEl.parentElement && !isResizableGroupEl(chartEl.parentElement)) {
        return { parent: chartEl.parentElement, afterEl: chartEl, chartEl };
      }
      return null;
    } catch (e) {}
    return null;
  }

  function clearLegacyTopBarLayoutOffsets() {
    if (lastAdjustedContentEl) {
      try {
        lastAdjustedContentEl.style.marginTop = '';
        lastAdjustedContentEl.style.maxHeight = '';
      } catch (e) {}
      lastAdjustedContentEl = null;
    }
    try {
      document.documentElement.classList.remove('vest-cortex-top-bar-active');
      document.body.classList.remove('vest-cortex-top-bar-active');
    } catch (e) {}
  }

  function ensureCortexTopBar() {
    if (!document.body) return null;
    const activeFirm = typeof getActivePerpFirm === 'function' ? getActivePerpFirm() : null;
    if (activeFirm && !activeFirm.enabled) {
      const existingBar = document.getElementById(CORTEX_TOP_BAR_ID);
      if (existingBar) existingBar.remove();
      clearLegacyTopBarLayoutOffsets();
      return null;
    }

    let bar = document.getElementById(CORTEX_TOP_BAR_ID);
    if (!bar) {
      bar = document.createElement('div');
      bar.id = CORTEX_TOP_BAR_ID;
      bar.setAttribute('role', 'region');
      bar.setAttribute('aria-label', 'Trading Cortex minimized windows dock');
    }

    const minimizedCount = typeof getActiveMinimizedWindowOrder === 'function'
      ? getActiveMinimizedWindowOrder().length
      : 0;
    const chartBottomMount = findChartBottomDockMountPoint();

    // Primary mode on any chart page: Cortex pill floats freely (draggable, default top-middle),
    // and minimized windows dock right below the chart viewport (hidden when 0 minimized!)
    if (chartBottomMount && chartBottomMount.parent && chartBottomMount.afterEl) {
      clearLegacyTopBarLayoutOffsets();

      if (bar.parentElement !== chartBottomMount.parent || bar.previousSibling !== chartBottomMount.afterEl) {
        chartBottomMount.parent.insertBefore(bar, chartBottomMount.afterEl.nextSibling);
      }

      bar.classList.remove('vest-cortex-hypernova-aligned');
      bar.classList.remove('vest-cortex-inflow-bar');
      bar.classList.add('vest-cortex-bottom-dock');
      bar.style.top = '';
      bar.style.left = '';
      bar.style.right = '';
      bar.style.marginTop = '';
      bar.style.marginLeft = '';
      bar.style.width = '100%';
      bar.style.height = '38px';
      bar.style.zIndex = '20';

      if (minimizedCount > 0) {
        bar.style.display = 'flex';
        try {
          const pStyle = window.getComputedStyle(chartBottomMount.parent);
          if (!pStyle || !pStyle.display || !pStyle.display.includes('flex') || pStyle.flexDirection !== 'column') {
            chartBottomMount.parent.style.display = 'flex';
            chartBottomMount.parent.style.flexDirection = 'column';
          }
          // NEVER overwrite style.flex on site containers / react-resizable-panels ([data-panel]),
          // which snaps the user's dragged chart splitter back to default! Only size raw unstyled iframes.
          const afterEl = chartBottomMount.afterEl;
          const isManagedPanel = Boolean(
            afterEl.hasAttribute('data-panel') ||
            afterEl.hasAttribute('data-panel-id') ||
            afterEl.hasAttribute('data-panel-size') ||
            afterEl.style.flex ||
            afterEl.style.flexGrow ||
            afterEl.style.height
          );
          if (!isManagedPanel && afterEl.tagName === 'IFRAME') {
            afterEl.style.flex = '1 1 0%';
            afterEl.style.minHeight = '0px';
          } else if (!isManagedPanel) {
            const aStyle = window.getComputedStyle(afterEl);
            if (aStyle && aStyle.minHeight === 'auto') {
              afterEl.style.minHeight = '0px';
            }
          }
        } catch (e) {}
      } else {
        bar.style.display = 'none';
      }
      return bar;
    }

    // Fallback (on non-chart pages like Portfolio / Markets): hide completely when 0 minimized windows
    bar.classList.remove('vest-cortex-bottom-dock');
    if (minimizedCount === 0) {
      clearLegacyTopBarLayoutOffsets();
      bar.style.display = 'none';
      return bar;
    }
    bar.style.display = 'flex';

    if (isHypernovaHost()) {
      const mount = findHypernovaInflowMountPoint();
      if (mount && mount.parent && mount.beforeEl) {
        // Clear any legacy fixed-bar layout offsets so normal flex/block flow handles top & bottom spacing cleanly
        if (lastAdjustedContentEl) {
          try {
            lastAdjustedContentEl.style.marginTop = '';
            lastAdjustedContentEl.style.maxHeight = '';
          } catch (e) {}
          lastAdjustedContentEl = null;
        }

        // If the main workspace container uses padding-top to clear a position:fixed header,
        // mount our bar as its FIRST CHILD so the container's own padding-top places our bar
        // right below the header with zero overlap and zero double-gap!
        let targetParent = mount.parent;
        let targetBefore = mount.beforeEl;
        try {
          const beforeStyle = window.getComputedStyle(mount.beforeEl);
          const beforePadTop = parseFloat(beforeStyle && beforeStyle.paddingTop) || 0;
          if (beforePadTop >= 24 && mount.beforeEl.firstChild) {
            targetParent = mount.beforeEl;
            targetBefore = mount.beforeEl.firstChild === bar ? bar.nextSibling : mount.beforeEl.firstChild;
          }
        } catch (e) {}

        if (bar.parentElement !== targetParent || (targetBefore && bar.nextSibling !== targetBefore)) {
          targetParent.insertBefore(bar, targetBefore);
        }
        try {
          if (!mount.beforeEl.style.minHeight) {
            mount.beforeEl.style.minHeight = '0px';
          }
        } catch (e) {}

        bar.classList.remove('vest-cortex-hypernova-aligned');
        bar.classList.add('vest-cortex-inflow-bar');
        bar.style.top = '';
        bar.style.left = '';
        bar.style.right = '';
        bar.style.height = `${CORTEX_BAR_HEIGHT}px`;
        bar.style.zIndex = '5';

        // Self-measure against Hypernova's actual rendered header bottom & left rail so our in-flow bar
        // NEVER overlaps the "Active Assessment / A1" header bar or the left icon sidebar!
        try {
          const headerRect = mount.headerEl ? mount.headerEl.getBoundingClientRect() : null;
          const headerBottom = (headerRect && headerRect.bottom >= 28 && headerRect.bottom <= 90)
            ? Math.ceil(headerRect.bottom)
            : getMainHeaderBottom();
          const leftInset = getHypernovaChartLeftInset();

          const currentMarginTop = parseFloat(bar.style.marginTop) || 0;
          const barRect = bar.getBoundingClientRect();
          const naturalTop = barRect.top - currentMarginTop;
          const neededMarginTop = Math.max(0, Math.ceil(headerBottom - naturalTop));
          bar.style.marginTop = neededMarginTop > 0 ? `${neededMarginTop}px` : '0px';

          const currentMarginLeft = parseFloat(bar.style.marginLeft) || 0;
          const naturalLeft = barRect.left - currentMarginLeft;
          const neededMarginLeft = Math.max(0, Math.ceil(leftInset - naturalLeft));
          if (neededMarginLeft > 0) {
            bar.style.marginLeft = `${neededMarginLeft}px`;
            bar.style.width = `calc(100% - ${neededMarginLeft}px)`;
          } else {
            bar.style.marginLeft = '0px';
            bar.style.width = '100%';
          }
        } catch (e) {
          bar.style.marginTop = '0px';
          bar.style.marginLeft = '0px';
          bar.style.width = '100%';
        }
        return bar;
      }

      // Hydration fallback before Hypernova's <header>/<main> finishes mounting
      const headerBottom = getMainHeaderBottom();
      const barMargin = (activeFirm && typeof activeFirm.barMarginBottom === 'number') ? activeFirm.barMarginBottom : CORTEX_BAR_MARGIN_BOTTOM;
      adjustLayoutForTopBar(headerBottom, CORTEX_BAR_HEIGHT, barMargin);
      if (bar.parentElement !== document.body) {
        document.body.appendChild(bar);
      }
      const leftInset = getHypernovaChartLeftInset();
      bar.classList.remove('vest-cortex-inflow-bar');
      bar.classList.add('vest-cortex-hypernova-aligned');
      bar.style.top = `${headerBottom}px`;
      bar.style.height = `${CORTEX_BAR_HEIGHT}px`;
      bar.style.left = `${leftInset}px`;
      bar.style.right = '0px';
      bar.style.width = 'auto';
      bar.style.zIndex = '15';
      return bar;
    }

    const headerBottom = getMainHeaderBottom();
    const barMargin = (activeFirm && typeof activeFirm.barMarginBottom === 'number') ? activeFirm.barMarginBottom : CORTEX_BAR_MARGIN_BOTTOM;
    adjustLayoutForTopBar(headerBottom, CORTEX_BAR_HEIGHT, barMargin);
    if (bar.parentElement !== document.body) {
      document.body.appendChild(bar);
    }
    bar.classList.remove('vest-cortex-hypernova-aligned');
    bar.classList.remove('vest-cortex-inflow-bar');
    bar.style.top = `${headerBottom}px`;
    bar.style.height = `${CORTEX_BAR_HEIGHT}px`;
    bar.style.left = '0px';
    bar.style.right = '0px';
    bar.style.width = '100%';
    bar.style.zIndex = '';
    return bar;
  }

  function initPanelManager() {
    if (!isTopWindow) return;

    ensureCortexTopBar();
    renderStudioHeaderPill();
    if (settings.enablePanelManagement !== false) {
      scheduleScanPanels(true);
    }

    if (!studioPillHeartbeat) {
      studioPillHeartbeat = setInterval(() => {
        if (!isExtensionValid()) {
          clearInterval(studioPillHeartbeat);
          studioPillHeartbeat = null;
          return;
        }
        ensureCortexTopBar();
        ensureBottomPositionsPanelManager();
        if (!studioPillEl || !studioPillEl.isConnected) {
          renderStudioHeaderPill();
        } else {
          dockStudioPillNextToMarketSelector(studioPillEl);
        }
        if (settings.newsBox && settings.newsBox.enabled) {
          if (!chartNewsBoxEl || !chartNewsBoxEl.isConnected) {
            renderChartNewsBox();
          } else {
            clampAndPositionChartNewsBox();
          }
        }
        if (settings.tradesBox && settings.tradesBox.enabled) {
          if (!chartTradesBoxEl || !chartTradesBoxEl.isConnected) {
            renderChartTradesBox();
          } else {
            clampAndPositionChartTradesBox();
          }
        }
        if (settings.diagnosticsBox && settings.diagnosticsBox.enabled) {
          if (!chartDiagnosticsBoxEl || !chartDiagnosticsBoxEl.isConnected) {
            renderChartDiagnosticsBox();
          } else {
            clampAndPositionChartDiagnosticsBox();
          }
        }
        /* [HEARTBEAT_CLEANUP_BLOCK]
        if (!studioPillEl || !studioPillEl.isConnected) {
          renderStudioHeaderPill();
        } else {
          dockStudioPillNextToMarketSelector(studioPillEl);
        }
        if (settings.newsBox && settings.newsBox.enabled) {
          if (!chartNewsBoxEl || !chartNewsBoxEl.isConnected) {
            renderChartNewsBox();
          } else {
            clampAndPositionChartNewsBox();
          }
        }
        if (settings.tradesBox && settings.tradesBox.enabled) { // resize-trades
          if (!chartTradesBoxEl || !chartTradesBoxEl.isConnected) {
            renderChartTradesBox();
          } else {
            clampAndPositionChartTradesBox();
      }
      if (settings.diagnosticsBox && settings.diagnosticsBox.enabled) {
        clampAndPositionChartDiagnosticsBox();
          }
        }
        if (settings.diagnosticsBox && settings.diagnosticsBox.enabled) {
          if (!chartDiagnosticsBoxEl || !chartDiagnosticsBoxEl.isConnected) {
            renderChartDiagnosticsBox();
          } else {
            clampAndPositionChartDiagnosticsBox();
          }
          }
        }
        */
      }, 900);
    }

    if (!panelObserver) {
      panelObserver = new MutationObserver((mutations) => {
        let isRelevant = false;
        for (let i = 0; i < mutations.length; i++) {
          const m = mutations[i];
          if (m.target && m.target.nodeType === 1) {
            const targetEl = m.target;
            if (
              targetEl.id === 'vest-minimized-dock' ||
              targetEl.id === 'vest-cortex-mobile-dock' ||
              targetEl.id === 'vest-studio-header-pill' ||
              targetEl.id === 'vest-studio-pill-drag-shield' ||
              targetEl.id === 'vest-panel-toggle-pill' ||
              targetEl.id === 'vest-template-bar-root' ||
              targetEl.id === 'vest-action-log-box' ||
              targetEl.id === 'vest-chart-news-box' ||
              targetEl.id === 'vest-chart-trades-box' ||
              targetEl.id === 'vest-chart-diagnostics-box' ||
              targetEl.classList.contains('vest-panel-header-bar') ||
              targetEl.classList.contains('vest-minimized-chip') ||
              targetEl.closest('#vest-minimized-dock') ||
              targetEl.closest('#vest-cortex-mobile-dock') ||
              targetEl.closest('#vest-studio-header-pill') ||
              targetEl.closest('#vest-panel-toggle-pill') ||
              targetEl.closest('#vest-template-bar-root') ||
              targetEl.closest('#vest-action-log-box') ||
              targetEl.closest('#vest-chart-news-box') ||
              targetEl.closest('#vest-chart-trades-box') ||
              targetEl.closest('#vest-chart-diagnostics-box') ||
              targetEl.closest('.vest-panel-header-bar')
            ) {
              continue;
            }
          }
          if (m.addedNodes && m.addedNodes.length > 0) {
            isRelevant = true;
            break;
          }
        }

        if (isRelevant) {
          dockStudioPillNextToMarketSelector(studioPillEl);
          if (settings.enablePanelManagement !== false) {
            scheduleScanPanels();
          }
        }
        scheduleSiteModalStackingSync();
      });

      try {
        panelObserver.observe(document.body, { childList: true, subtree: true });
      } catch (e) {}
    }

    document.addEventListener('mousemove', onPanelDragMove);
    document.addEventListener('mouseup', onPanelDragEnd);
  }

  let siteModalStackSyncTimer = null;
  let siteModalStackInterval = null;

  function isCortexOwnedElement(el) {
    if (!el || el.nodeType !== 1) return false;
    if (el.id && el.id.startsWith('vest-')) return true;
    const cls = typeof el.className === 'string' ? el.className : '';
    if (/\bvest-/.test(cls)) return true;
    if (el.closest && el.closest('[id^="vest-"], .vest-tvs-overlay, .vest-bottom-panel-detached')) return true;
    return false;
  }

  function detectOpenSiteModalOverlay() {
    if (!isTopWindow || !document.body) return false;
    try {
      // 1. Standard semantic dialogs / Radix / Base UI / MUI portals (excluding our own Cortex modals)
      const dialogCandidates = document.querySelectorAll(
        '[role="dialog"], [role="alertdialog"], [aria-modal="true"], [data-slot="dialog-content"], [data-slot="dialog-overlay"], [data-radix-dialog-overlay]'
      );
      for (let i = 0; i < dialogCandidates.length; i++) {
        const el = dialogCandidates[i];
        if (isCortexOwnedElement(el)) continue;
        if (el.getAttribute('data-state') === 'closed') continue;
        const r = el.getBoundingClientRect();
        if (r.width < 120 || r.height < 80) continue;
        const cs = window.getComputedStyle(el);
        if (cs.display === 'none' || cs.visibility === 'hidden' || parseFloat(cs.opacity || '1') <= 0.05) continue;
        return true;
      }

      // 2. Custom full-screen fixed modal backdrops (e.g. Tailwind `fixed inset-0 bg-black/70` without role="dialog")
      const vw = window.innerWidth || 0;
      const vh = window.innerHeight || 0;
      if (vw > 200 && vh > 200) {
        const backdropCandidates = document.querySelectorAll(
          '[class*="inset-0"], [class*="backdrop" i], [class*="modal" i], [class*="overlay" i]'
        );
        for (let i = 0; i < backdropCandidates.length && i < 80; i++) {
          const el = backdropCandidates[i];
          if (isCortexOwnedElement(el)) continue;
          if (el === document.body || el.id === '__next' || el.id === 'root' || el.tagName === 'MAIN') continue;
          if (el.getAttribute('data-state') === 'closed') continue;
          const cs = window.getComputedStyle(el);
          if (cs.position !== 'fixed' || cs.display === 'none' || cs.visibility === 'hidden' || cs.pointerEvents === 'none') continue;
          if (parseFloat(cs.opacity || '1') <= 0.05) continue;
          const r = el.getBoundingClientRect();
          if (r.width < vw * 0.85 || r.height < vh * 0.85) continue;
          const hasBg = cs.backgroundColor && cs.backgroundColor !== 'rgba(0, 0, 0, 0)' && cs.backgroundColor !== 'transparent';
          const hasBlur = (cs.backdropFilter && cs.backdropFilter !== 'none') || (cs.webkitBackdropFilter && cs.webkitBackdropFilter !== 'none');
          if (hasBg || hasBlur) return true;
        }
      }
    } catch (e) {}
    return false;
  }

  function syncSiteModalStackingState() {
    if (!isTopWindow || !document.body) return;
    const hasSiteModal = detectOpenSiteModalOverlay();
    const currentlySet = document.body.classList.contains('vest-site-modal-open');
    if (hasSiteModal !== currentlySet) {
      document.body.classList.toggle('vest-site-modal-open', hasSiteModal);
    }
    if (hasSiteModal && studioMenuOpen && typeof closeStudioDropdown === 'function') {
      closeStudioDropdown();
    }
  }

  function scheduleSiteModalStackingSync() {
    if (siteModalStackSyncTimer) return;
    siteModalStackSyncTimer = setTimeout(() => {
      siteModalStackSyncTimer = null;
      syncSiteModalStackingState();
    }, 40);
  }

  if (isTopWindow && !siteModalStackInterval) {
    siteModalStackInterval = setInterval(() => {
      if (!isExtensionValid()) {
        clearInterval(siteModalStackInterval);
        siteModalStackInterval = null;
        return;
      }
      syncSiteModalStackingState();
    }, 350);
  }

  /**
   * Finds the market selector dropdown pill (e.g. "★ SOL Solana 5x ⌄") in the top market bar
   * so we can place our Vest Studio dropdown pill directly to its left.
   */
  function findMarketSelectorElement() {
    // 1. Direct detection of the instrument selector pill in the top-left market bar
    //    (e.g., contains leverage badge like "5x", "10x", "20x", "50x", pair format like "HYPE-USD", or star/chevron SVGs at top: 36..135, left: 10..260)
    const allInteractive = document.querySelectorAll('button, div[role="button"], a, div');
    for (let i = 0; i < allInteractive.length; i++) {
      const el = allInteractive[i];
      if (el.id === 'vest-studio-header-pill' || el.closest('#vest-studio-header-pill')) continue;
      const r = el.getBoundingClientRect();
      if (r.top >= 36 && r.top <= 135 && r.left >= 10 && r.left <= 260 && r.width >= 60 && r.width <= 320 && r.height >= 24 && r.height <= 56) {
        const txt = (el.textContent || '').trim();
        const hasLeverage = /\b\d+(\.\d+)?x\b/i.test(txt);
        const hasPairFormat = /\b[A-Z0-9]{2,10}(?:-[A-Z0-9]{2,10}|_PERP|\/USD|\s*PERP)\b/i.test(txt);
        const hasSvg = el.querySelectorAll('svg').length >= 1;
        if ((hasLeverage || hasPairFormat) && el.parentElement && el.parentElement !== document.body) {
          // Walk up if parent is just a tight single-child wrapper around the button
          let targetPill = el;
          while (
            targetPill.parentElement &&
            targetPill.parentElement !== document.body &&
            targetPill.parentElement.children.length === 1
          ) {
            const pr = targetPill.parentElement.getBoundingClientRect();
            if (pr.width <= 340 && pr.height <= 64) {
              targetPill = targetPill.parentElement;
            } else {
              break;
            }
          }
          if (targetPill.parentElement && targetPill.parentElement !== document.body) {
            return { marketPillEl: targetPill, rowEl: targetPill.parentElement };
          }
        }
      }
    }

    // 2. Locate the "Mid Price", "Index Price", "Mark / Mid", "Open Interest", or "24h Change" stat label in the top market header
    const allEls = document.querySelectorAll('span, div, p, button');
    let midPriceEl = null;
    for (let i = 0; i < allEls.length; i++) {
      const el = allEls[i];
      if (el.children.length > 2) continue;
      const txt = (el.textContent || '').trim();
      if (
        txt === 'Mid Price' ||
        txt === 'Index Price' ||
        txt === '24h Change' ||
        txt === 'Mark / Mid' ||
        txt.includes('Mark / Mid') ||
        txt === 'Open Interest' ||
        txt === '24h Volume'
      ) {
        const r = el.getBoundingClientRect();
        if (r.top >= 25 && r.top <= 145) {
          midPriceEl = el;
          break;
        }
      }
    }

    if (midPriceEl) {
      const midRect = midPriceEl.getBoundingClientRect();
      let curr = midPriceEl.parentElement;
      while (curr && curr !== document.body) {
        const r = curr.getBoundingClientRect();
        if (r.width > 260 && r.height >= 26 && r.height <= 95 && r.top < 140) {
          for (let c = 0; c < curr.children.length; c++) {
            const child = curr.children[c];
            if (child.id === 'vest-studio-header-pill') continue;
            if (child.contains(midPriceEl)) break;
            const cr = child.getBoundingClientRect();
            if (cr.left < midRect.left && cr.width >= 60 && cr.width <= 350 && cr.height >= 24) {
              return { marketPillEl: child, rowEl: curr };
            }
          }
        }
        curr = curr.parentElement;
      }
    }

    return null;
  }

  let cachedMarketRowEl = null;
  let cachedMarketPillEl = null;
  let studioPillHostIframe = null;

