    chartDiagnosticsBoxEl.style.width = db.collapsed ? 'auto' : `${db.boxWidth}px`;
    chartDiagnosticsBoxEl.style.background = hexToRgba(db.bgColor || '#0f172a', (Number(db.bgOpacity ?? 94)) / 100);
